 one.erase(one.begin());
 assert(it.fi <= it.se);
 one.insert(it);
 }
 }
 else {
 // shifter + idx >= x
 // idx >= x - shifter
 ll lim = x - shifter;

 while (!one.empty() && one.rbegin() -> fi >= lim) {
 one.erase(--one.end());
 }

 if (!one.empty() && one.rbegin() -> se >= lim) {
 pll it = mp(one.rbegin() -> fi, lim - 1);
 one.erase(--one.end());
 assert(it.fi <= it.se);
 one.insert(it);
 }
 }

 shifter = x - shifter;
 sign *= -1;
 }
 else {
 sign = -1;
 shifter = x;
 int lim = min(arr[i - 1] - 1, x - 1);

 if (1 <= lim) {
 one.insert(mp(1, lim));
 }
 }

