 --it;

 if (it -> fi <= val && val <= it -> se) {
 found = 1;
 }
 }

 if (found) {
 two = y;
 }
 else {
 one.insert(mp(val, val));
 }
 }
 }

 int ans;

 if (two != -1) {
 ans = zero + 2;
 }
 else if (!one.empty()) {
 ans = zero + 1;
