 if (arr[ni][nj] < arr[i][j]) {
 follow[i][j] = dir;
 }
 else if ((i + j) % 2 == 0 && arr[ni][nj] == arr[i][j]) {
 addEdge(id(i, j), id(ni, nj), 1);
 }
 }
 }

 if (follow[i][j] == -1) {
 // important vertex
 if ((i + j) % 2) {
 addEdgeLim(id(i, j), T);
 }
 else {
 addEdgeLim(S, id(i, j));
 }
 }
 else {
 if ((i + j) % 2) {
 addEdge(id(i, j), T, 1);
 }
 else {
 addEdge(S, id(i, j), 1);
 }
 }
 }
 }

 for (int i = 0; i <= T; ++i) {
 if (cap[0][i] > 0) {
 addEdge(newS, i, cap[0][i]);
 }

 if (cap[1][i] > 0) {
 addEdge(i, newT, cap[1][i]);
 }
 }

 addEdge(T, S, INF);
 maxFlow();

 for (int id : adj[newS]) {
 if (e[id].f != e[id].c) {
 printf("NO\n");
 return;
 }
 }

 vvi ansv, ansc;
 ansv = ansc = vvi(n, vi(m));

 for (int i = 0; i < n; ++i) {
 for (int j = 0; j < m; ++j) {
 int dir = follow[i][j];

 if (dir != -1) {
 int ni = i + dx[dir], nj = j + dy[dir];
 ansv[i][j] = arr[i][j] - arr[ni][nj];
 ansc[i][j] = dir;
 }
 }
 }

 for (Edge it : e) {
 int v = it.v, to = it.to;

 if (max(v, to) < n * m && it.f == it.c && it.c == 1) {
 int ax = v / m, ay = v % m;
 int bx = to / m, by = to % m;
 ansv[ax][ay] = arr[ax][ay] - 1;
 ansv[bx][by] = 1;

 for (int dir = 0; dir < 4; ++dir) {
 if (mp(ax + dx[dir], ay + dy[dir]) == mp(bx, by)) {
 ansc[ax][ay] = dir;
 ansc[bx][by] = (dir + 2) % 4;
 }
 }
 }
 }

 printf("YES\n");

 for (int i = 0; i < n; ++i) {
 for (int j = 0; j < m; ++j) {
 printf("%d%c", ansv[i][j], " \n"[j == m - 1]);
 }
 }

 for (int i = 0; i < n; ++i) {
 for (int j = 0; j < m; ++j) {
 printf("%c%c", dc[ansc[i][j]], " \n"[j == m - 1]);
 }
 }
}

int main() {
 int tt;
 scanf("%d", &tt);

 while (tt--) {
 solve();
 }

 return 0;
}
