 cin >> n;
 if (gcd_sum(n) != 1) {
 cout << n << endl;
 } else if (gcd_sum(n + 1) != 1) {
 cout << n + 1 << endl;
 } else if (gcd_sum(n + 2) != 1) {
 cout << n + 2 << endl;
 }
 }
 return 0;
}
