 all1 = m - 1;
 memset(ta, -1, sizeof(ta));
 memset(tb, -1, sizeof(tb));
 ForE(i, 1, n){
 tb[all1 ^ (i - 1)] = b[i];
 ta[n - i] = -2;
 }

 For(i, 0, m){
 c[all1 ^ i] = max(tb[i], 0);
 }
 For(bit, 0, lm){
 For(msk, 0, m){
 if (msk >> bit & 1){
 c[msk] ^= c[msk ^ (1 << bit)];
 }
 }
 }
 For(i, 0, m){
 if (tb[i] == -1){
 c[all1 ^ i] = 0;
 }
 }
 For(bit, 0, lm){
 For(msk, 0, m){
 if (msk >> bit & 1){
 c[msk] ^= c[msk ^ (1 << bit)];
 }
 }
 }
 For(i, 0, m){
