#include "bits/stdc++.h"

using namespace std;

const int mod = (int) 1e9 + 7;

int inv(int x) {
 int res = 1, n = mod - 2;
 while (n) {
 if (n & 1) {
 res = res * 1ll * x % mod;
 }
 x = x * 1ll * x % mod;
 n /= 2;
 }
 return res;
}

const int N = (int) 2e5 + 22, K = 18;
vector g[N];
pair a[N];
int n, q, ans = 1;
int h[N], up[N][K], lg[N];
vector> graph[K]; // lower vertex1, lower vertex2, time, vertex with direction
vector> gr[N];
vector> edges;

struct dsu {
 vector p, sz;

 void build(int n) {
 p.resize(n);
 sz.resize(n);
 for (int i = 0; i < n; i++) {
 p[i] = i;
 sz[i] = 1;
 }
 }

 int get(int v) {
 return (v == p[v] ? v : p[v] = get(p[v]));
 }

 bool merge(int v, int u) {
 v = get(v), u = get(u);
 if (v != u) {
 if (sz[v] > sz[u]) {
 swap(v, u);
 }
 p[v] = u;
 sz[u] += sz[v];
 return true;
 }
 return false;
 }
} G, dsu[K];

void dfs(int v, int pr, int d) {
 h[v] = d;
 up[v][0] = pr;
 for (int j = 1; j < K; j++) {
 up[v][j] = up[up[v][j - 1]][j - 1];
 }
 for (auto u : g[v]) {
 dfs(u, v, d + 1);
 }
}

int la(int v, int x) {
 for (int j = 0; j < K; j++) {
 if (x >> j & 1) {
 v = up[v][j];
 }
 }
 return v;
}

int lca(int v, int u) {
 if (h[v] > h[u]) {
 swap(v, u);
 }
 u = la(u, h[u] - h[v]);
 if (v == u) {
 return v;
 }
 for (int j = K - 1; j >= 0; j--) {
 if (up[v][j] != up[u][j]) {
 v = up[v][j], u = up[u][j];
 }
 }
 return up[v][0];
}

int id(int v) {
 return (v > 0 ? v : -v + n);
}

int sgn(int v) {
 return (v > 0 ? 1 : -1);
}

void add_edge(int j, int v, int u, int t) {
 if (dsu[j].merge(id(v), id(u))) {
 if (j > 0) {
 if (sgn(v) == sgn(u)) {
 add_edge(j - 1, v, u, t);
 add_edge(j - 1, sgn(v) * up[abs(v)][j - 1], sgn(u) * up[abs(u)][j - 1], t);
 } else {
 if (sgn(v) == -1) {
 swap(v, u);
 }
 add_edge(j - 1, v, sgn(u) * up[abs(u)][j - 1], t);
 add_edge(j - 1, sgn(v) * up[abs(v)][j - 1], u, t);
 }
 } else {
 edges.push_back({abs(v), abs(u), t});
 }
 }
}

void add(int v, int u, int x, int y, int t, int type1, int type2) {
 if (h[v] < h[u]) {
 swap(v, u);
 }
 if (h[x] < h[y]) {
 swap(x, y);
 }
 assert(h[v] - h[u] == h[x] - h[y]);
 int g = lg[h[v] - h[u]];
 if (type1 == type2) {
 add_edge(g, type1 * v, type2 * x, t);
 add_edge(g, type1 * la(v, h[v] - h[u] - (1 << g) + 1), type2 * la(x, h[x] - h[y] - (1 << g) + 1), t);
 } else {
 add_edge(g, type1 * v, type2 * la(x, h[x] - h[y] - (1 << g) + 1), t);
 add_edge(g, type1 * la(v, h[v] - h[u] - (1 << g) + 1), type2 * x, t);
 }
}

void merge(int v, int u) {
 v = G.get(v), u = G.get(u);
 if (v != u) {
 G.merge(v, u);
 if (G.sz[v] > G.sz[u]) {
 swap(v, u);
 }
 if (a[v].first <= a[v].second) {
 ans = ans * 1ll * inv(a[v].second - a[v].first + 1) % mod;
 }
 if (a[u].first <= a[u].second) {
 ans = ans * 1ll * inv(a[u].second - a[u].first + 1) % mod;
 }
 a[u].first = max(a[u].first, a[v].first);
 a[u].second = min(a[u].second, a[v].second);
 if (a[u].first > a[u].second) {
 ans = 0;
 } else {
 ans = ans * 1ll * (a[u].second - a[u].first + 1) % mod;
 }
 }
}

int main {
