 cin.tie(0);
 cout.tie(0);
 for (int j = 2; j < N; j++) {
 lg[j] = lg[j / 2] + 1;
 }
 cin >> n;
 for (int i = 2; i <= n; i++) {
 int v;
 cin >> v;
 g[v].push_back(i);
 }
 for (int i = 1; i <= n; i++) {
 cin >> a[i].first >> a[i].second;
 ans = ans * 1ll * (a[i].second - a[i].first + 1) % mod;
 }
 dfs(1, 1, 0);
 cin >> q;
 for (int j = 0; j < K; j++) {
 dsu[j].build(2 * n + 1);
 }
 for (int i = 0; i < q; i++) {
 int v, u, x, y;
 cin >> v >> u >> x >> y;
 int w = lca(v, u);
 int z = lca(x, y);
 if (h[v] - h[w] > h[x] - h[z]) {
 swap(v, x);
 swap(u, y);
 swap(w, z);
 }
 if (v != w) {
 int d = h[v] - h[w];
 int v2 = la(v, d - 1);
 int x2 = la(x, d - 1);
 add(v, v2, x, x2, i, 1, 1);
 v = up[v2][0];
 x = up[x2][0];
 }
 if (x != z) {
 int d = h[x] - h[z];
 int v2 = la(u, (h[u] - h[v]) - d);
 int x2 = la(x, d - 1);
 add(v, up[v2][0], x, x2, i, -1, 1);
 v = v2;
 x = up[x2][0];
 }
 add(v, u, x, y, i, (h[v] > h[u] ? 1 : -1), (h[x] > h[y] ? 1 : -1));
 }
