}
void build(int u,int l,int r)
{
 cov[u] = -1;
 if(l == r) {mn[u] = mx[u] = num[l] ; return;}
 build(u<<1 , l , (l + r >> 1)) ; build(u<<1|1 , (l + r >> 1) + 1 , r);
 rec(u) ; return;
}
