 for (int l = 0, r = n - 1, mid; l <= r; ) {
 mid = l + r >> 1;
 if (n - floor(mid / k) <= mid + mid) {
 i = mid; r = mid - 1;
 } else {
 l = mid + 1;
 }
 }
 solve((n - 1) / 2, x, 0, z, a);
 solve((i - 1) / 2, x, 0, z, b);
 solve((n - 2) / 2, x, y, z, c);
 solve((i - 2) / 2, x, y, z, d);
 ans = i + (i % 2 ? -1 : 1) * ((a - b) - (c - d));
 if ((n - i) % 2) { ans = n - ans; }
