A sequence is almost-increasing if it does not contain three consecutive elements $x, y, z$ such that $x\ge y\ge z$.

For each query $[l, r]$, we want to find the length of the longest almost-increasing subsequence of the subarray $a_l, a_{l+1}, \dots, a_r$.

Call position $i$ (for $1 < i < n$) a "downhill" if $a[i-1] \geq a[i] \geq a[i+1]$. For a query $[l,r]$, the answer is $(r - l + 1)$ minus the number of downhill positions in the range $(l, r)$ (exclusive of endpoints). This is because each downhill position forces us to remove one element.

We can precompute a prefix sum array $p$ where $p[i]$ counts the number of downhill positions up to index $i$, and answer each query in $O(1)$.

```cpp
#include "bits/stdc++.h"
using namespace std;
typedef vector<int> vi;

int main {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n,q; cin >> n >> q;
    vi a(n);
    for(int& i : a) cin >> i;
    vi p(n-1);
    for(int i=1;i<n-1;++i) {
        int downhill = a[i-1]>=a[i] and a[i]>=a[i+1];
        p[i] = p[i-1] + downhill;
    }
    while(q--) {
        int l,r; cin >> l >> r;
        --l,--r;
        if(l==r) {
            cout << "1\n";
        } else {
            int ans = (r-l+1) - p[r-1] + p[l];
            cout << ans << '\n';
        }
    }
}
```

**Hint 1**

Can you find a necessary condition for whether a Fish Subgraph exists?

**Hint 2**

For the Fish Subgraph to exist, the graph must have a cycle with one node in the cycle having degree at least 4.

**Hint 3**

When the necessary condition is satisfied, actually, you can always find a Fish Subgraph. Try to prove this, and see if your proof can be turned into an algorithm.

**Editorial**

For each node $u$ with degree $\geq 4$, and for each neighbor $v$ of $u$, try to find a path from $u$ to $v$ without using the direct edge $(u,v)$. If such a path exists, we have found a cycle containing $u$, and since $u$ has degree $\geq 4$, there are at least 2 neighbors of $u$ not on the cycle (we can always shorten the cycle to minimize it, ensuring we have extra neighbors). Output the cycle plus the two extra edges from $u$.

If no such node and cycle exists, output "NO".

```cpp
#include "bits/stdc++.h"
using namespace std;
#define all(x) begin(x),end(x)
typedef vector<int> vi;
typedef vector<vi> vvi;
typedef pair<int,int> pi;

void solve {
    int n,m; cin >> n >> m;
    vvi adj(n);
    while(m--) {
        int u,v; cin >> u >> v;
        --u,--v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    // find cycle and node with big degree.
    for(int u=0;u<n;++u) if(adj[u].size>=4) for(int v : adj[u]) {
        // find path from u to v, without edge (u,v)
        vi cur;
        vi p;
        vector<bool> vis(n);
        auto dfs = [&](auto&& self, int at) -> void {
            vis[at]=1;
            cur.push_back(at);
            if(at==v) {
                p=cur;
                return;
            }
            for(int to : adj[at]) if(!vis[to]) {
                if(at==u and to==v) continue;
                self(self,to);
                if(!p.empty) return;
            }
            cur.pop_back;
        };
        dfs(dfs,u);
        if(p.empty) continue;
        // found cycle, with a node with degree >=4
        vi extra = adj[u];
        extra.resize(4);
        int mn = p.size;
        for(auto i : extra) {
            auto it = find(all(p),i);
            if(it!=p.begin+1) {
                mn = min(mn,int(it-p.begin)+1);
            }
        }
        p.resize(mn);
        partition(all(extra),[&](int i) {return count(all(p),i)==0;});
        extra.resize(2);

        cout << "YES\n";
        cout << p.size+2 << '\n';
        auto out = [&](int a, int b) {cout << a+1 << ' ' << b+1 << '\n';};
        int prv=p.back;
        for(auto i : p) {
            out(i,prv);
            prv=i;
        }
        out(u,extra[0]);
        out(u,extra[1]);
        return;
    }

    cout << "NO\n";
}

int main {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t; cin >> t;
    while(t--) solve;
}
```

Let $\Delta^d A$ denote the $d$-th finite difference of polynomial $A$. The key observation is that for similar polynomials $A(x)$ and $B(x) = A(x+s)$, applying the finite difference operator $d$ times gives constants $\Delta^d A$ and $\Delta^d B = \Delta^d A$ (both are the leading coefficient times $d!$). Applying the finite difference operator $d-1$ times gives linear polynomials $\Delta^{d-1} A(x)$ and $\Delta^{d-1} B(x) = \Delta^{d-1} A(x+s)$.

Since $\Delta^{d-1} A(x)$ is linear with leading coefficient $c \cdot d$ (where $c$ is the leading coefficient of $A$), we can recover $s$ from the values of $\Delta^{d-1} A$ and $\Delta^{d-1} B$ at $x=0$:

$$\Delta^{d-1} B(0) = \Delta^{d-1} A(s)$$

Using the Newton forward difference formula, $\Delta^{d-1} A(0)$ can be computed from the given values. Similarly for $\Delta^{d-1} B(0)$. Their difference divided by the leading finite difference gives $s$.

More precisely, if we define weighted combinations using $c_i = (-1)^{d-i} / (i! \cdot (d-i)!)$, we can extract $s$ as:

$$s = \frac{2 \cdot \sum_i (A(i) - B(i)) \cdot c_i \cdot (d(d+1)/2 - i)}{d \cdot \sum_i (A(i) + B(i)) \cdot c_i}$$

```cpp
void solve {
    int d;
    cin >> d;
    vector<base> A(d + 1), B(d + 1);
    copy_n(istream_iterator<base>(cin), d + 1, begin(A));
    copy_n(istream_iterator<base>(cin), d + 1, begin(B));
    base s = 0, k2 = 0;
    auto coef = [&](int i) {
        return base((d - i) % 2 ? -1 : 1) * rfact<base>(i) * rfact<base>(d - i);
    };
    for(int i = 0; i <= d; i++) {
        s += (A[i] - B[i]) * coef(i) * (d * (d + 1) / 2 - i);
        k2 += (A[i] + B[i]) * coef(i);
    }
    s *= base(2) / (k2 * d);
    cout << s << "\n";
}
```

Instead of caring about the positions of all the toys, we only need to care about the position of the special toy with index $k$. The other toys can be treated as undistinguishable.

The intended way of solving this problem is playing the game in the webpage, trying to come up with some simple combinations of operations that make the special toy move to another position in a predictable way. Using these building blocks in a smart way, finding a way to move the special toy to the topleft.

As the size of the grid can be up to $100\,000$ and we can make $1\,000\,000$ moves, we will be aiming for a solution which does a linear number of moves.

There are lots of potential solutions which use a linear number of moves, here is a relatively painless one:

Do casework on $k$:

- Case $1$: If $1 \leq k \lt \frac{n-1}{2}$, we initally make one $\texttt{R}$ button press to align the toys with the right boundary. After this, there is an easy pattern to expose all the toys in the left halve, one by one: $\texttt{DRURDRUR...}$ repeated. When the special toy is exposed, the repeating pattern is stopped, and $\texttt{DL}$ are pressed. Toy $k$ will be moved to the topleft corner.

- Case $2$: If $k = \frac{n-1}{2}$, the puzzle can be solved in two moves: $\texttt{DL}$.

- Case $3$: If $\frac{n-1}{2} \lt k \leq n-2$, we try to reduce back to case $1$, by moving the special toy to the left halve, and ensuring that all other toys are in the top row. Using symmetry, we can apply case $1$ to $k^\prime = n-1 - k$, but mirror all horizontal moves, to move the toy to the topright corner. The other toys are no longer all in the top row. To fix this, the last pattern we need is again $\texttt{DRURDRUR...}$ repeated. After a while of repeating this, all toys will be in the right halve of the board, occupying the top and bottom row. To finish moving the special toy (which stayed in the topright corner), we do the buttons presses $\texttt{LDRU}$. All toys end up in the top row, and the special toy will be at position $k_\text{new} = \frac{n-1}{2} - 1$, so this successfully reduces to case $1$.

How many moves does this take? In case $1$ the pattern $\texttt{DRUR}$ needs to be repeated at most $\approx \frac{n}{2}$ times. In case $3$, we need to use the first pattern $\frac{n}{2}$ times, and we use the second pattern $\frac{n}{2}$ times. We reduce down to case $1$, but luckily the special toy is already close to the correct position, so only a constant number of extra moves are done.

So in total, this solution uses $O(1) + \max \left( 4\frac{n}{2}, 4 \cdot 2 \frac{n}{2} \right) = 4n + O(1)$ moves. So this solution fits well within the constraints, although it is pretty wasteful.

Bonus: Can you prove that the optimal number of moves needed in the worstcase (over all $k$) for a width of $n$ is $\Omega(n)$? We only did some testing of small cases, with a bruteforce BFS solution, and found that the worstcase is around $n/2$ button presses.

```cpp
#include "bits/stdc++.h"
using namespace std;

int main {
    int n,k; cin >> n >> k;
    --k;
    int half = (n-3)/2;
    string res = "";
    if(k==half) {
        res = "DL";
    } else {
        while(true) {
            if(k<half) {
                res+="R";
                int need = half-1-k;
                while(need--) {
                    res+="DRUR";
                }
                res+="DL";
                break;
            } else {
                int need = k-half-1;
                while(need--) {
                    res+="LDLU";
                }
                res+="LDR";
                for(int i=0;i<half+1;++i) {
                    res+="DRUR";
                }
                res+="LDRU";
                k = half-1;
            }
        }
    }
    cout << res << '\n';
}
```

description:
An integer template is a string consisting of digits and/or question marks.

A positive (strictly greater than $$$0$$$) integer matches the integer template if it is possible to replace every question mark in the template with a digit in such a way that we get the decimal representation of that integer without any leading zeroes.

For example:

- $$$42$$$ matches 4?;
- $$$1337$$$ matches ????;
- $$$1337$$$ matches 1?3?;
- $$$1337$$$ matches 1337;
- $$$3$$$ does not match ??;
- $$$8$$$ does not match ???8;
- $$$1337$$$ does not match 1?7.

You are given an integer template consisting of at most $$$5$$$ characters. Calculate the number of positive (strictly greater than $$$0$$$) integers that match it.

editorial_cleaned:
In a positive integer, the first digit is from $1$ to $9$, and every next digit can be any. This allows us to implement the following combinatorial approach:
• calculate the number of different values for the first digit, which is $0$ if the first character of $s$ is 0, $1$ if the first character of $s$ is any other digit, or $9$ if the first character of $s$ is ?;
• calculate the number of different values for each of the other digits, which is $1$ if the corresponding character of $s$ is a digit, or $10$ if it is ?;
• multiply all these values.

input_format:
The first line contains one integer $$$t$$$ ($$$1 \le t \le 10^4$$$) — the number of test cases.

Each test case consists of three lines:

- the first line contains one integer $$$n$$$ ($$$2 \le n \le 2 \cdot 10^5$$$);
- the second line contains $$$n$$$ integers $$$a_1, a_2, \dots, a_n$$$ ($$$1 \le a_i \le n$$$);
- the third line contains $$$n$$$ integers $$$a'_1, a'_2, \dots, a'_n$$$ ($$$1 \le a'_i \le n$$$).

Additional constraints on the input:

- the sum of $$$n$$$ over all test cases does not exceed $$$2 \cdot 10^5$$$;
- it is possible to obtain the array $$$a'$$$ by sorting one subarray of $$$a$$$;
- $$$a' \ne a$$$ (there exists at least one position in which these two arrays are different).

note:
In the first test case, one of the optimal sequences of operations is the following:

1. Move right: pointer is moving into cell $$$1$$$;
2. Press Shift;
3. Release Shift: cell $$$1$$$ is colored black;
4. Move right: pointer is moving into cell $$$2$$$;
5. Move right: pointer is moving into cell $$$3$$$;
6. Press Shift;
7. Move right: pointer is moving into cell $$$4$$$;
8. Release Shift: cells $$$3$$$ and $$$4$$$ are colored in black.

In the second test case, we can color at most $$$8$$$ cells, while we need $$$20$$$ cell to color.

In the third test case, one of the optimal sequences of operations is the following:

1. Move right: pointer is moving into cell $$$1$$$;
2. Move right: pointer is moving into cell $$$2$$$;
3. Move right: pointer is moving into cell $$$3$$$;
4. Press Shift;
5. Move right: pointer is moving into cell $$$4$$$;
6. Move right: pointer is moving into cell $$$5$$$;
7. Release Shift: cells $$$3$$$, $$$4$$$ and $$$5$$$ are colored in black.

output_format:
For each test case print

- 0, if it is possible to sort the permutation without preliminary exchange;
- 1, if it is possible to sort the permutation with one preliminary exchange, but not possible without preliminary exchange;
- -1, if it is not possible to sort the permutation with at most one preliminary exchange.

editorial_cleaned:
**Hint 1**

Sort the array $b$, and fix the values from $a_n$ to $a_1$.

**Solution**

First, we can sort the array $b$, as it does not change the answer.

Let's try to choose the values of $a$ from $a_n$ to $a_1$. How many ways are there to choose the value of $a_i$?

The new $a_i$ must satisfies $a_i \gt b_i$. But some of the candidates are already chosen as $a_j$ for some $j \gt i$. However, since $a_j \gt b_j \ge b_i$, we know that there are exactly $(n - i)$ candidates already chosen previously by all values of $j \gt i$. So, there are (number of $k$ such that $a_k \gt b_i$) $- (n - i)$ ways to choose the value of $a_i$.

We can use two pointers or binary search to efficiently find the (number of $k$ such that $a_k \gt b_i$) for all $i$.

Time complexity: $\mathcal O(n \log n)$.

**Implementation**

```
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MOD = 1e9 + 7;

struct testcase{
    testcase{
        int n; cin >> n;
        vector<int> a(n);
        for (int i=0; i<n; i++) cin >> a[i];
        sort(a.begin, a.end);
        vector<int> b(n);
        for (int i=0; i<n; i++) cin >> b[i];
        sort(b.begin, b.end, greater<>);
        ll result = 1;
        for (int i=0; i<n; i++){
            int geq_count = a.size - (upper_bound(a.begin, a.end, b[i]) - a.begin);
            result = result * max(geq_count - i, 0) % MOD;
        }
        cout << result << "\n";
    }
};

signed main{
    cin.tie(0)->sync_with_stdio(0);
    int t; cin >> t;
    while (t--) testcase;
}
```

**Hint 1**

What is the minimum cost to sort just one subarray?

**Hint 2**

What happens when two operations intersect each other?

**Hint 3**

When can we sort two adjacency ranges independently?

**Hint 4**

Try to calculate the contribution of each position.

**Solution**

Let $a[l..r]$ denotes the subarray $a_l,a_{l+1},\ldots,a_r$.

Observation 1: In an optimal sequence of operations for one subarray, there will be no two operations that intersect each other. In other words, a subarray will be divided into non-overlapping subarrays, and we will apply a range-sort operation to each subarray.

Proof: Suppose there are two operations $[l_1,r_1]$ and $[l_2,r_2]$ that intersect each other, we can replace them with one operation $[\min(l_1,l_2),\max(r_1,r_2)]$ which does not increase the cost.

Observation 2: Consider $k$ positions $l\le i_1 \lt i_2 \lt \ldots \lt i_k \lt r$, then we can sort subarrays $a[l..i_1],$ $a[i_1+1..i_2],$ $\ldots,$ $a[i_k+1..r]$ independently iff $\max(a[l..i_x]) \lt \min(a[i_x+1..r])$ for all $1\le x\le k$.

Proof: The obvious necessary and sufficient condition required to sort subarrays $a[l..i_1],$ $a[i_1+1..i_2],$ $\ldots,$ $a[i_k+1..r]$ independently is $\max(a[i_{x-1}+1..i_x]) \lt \min(a[i_x+1..i_{x+1}])$ for all $1\le x\le k$, here we denote $x_0=l-1$ and $x_{k+1}=r$. It is not hard to prove that this condition is equal to the one stated above.

With these observations, we can conclude that the answer for a subarray $a[l..r]$ equals the $r-l$ minus the number of positions $k$ such that $l\le k\lt r$ and $\max(a[l..k]) \lt \min(a[k+1..r])$ $(*)$. Let us analyze how to calculate the sum of this value over all possible $l$ and $r$.

Consider a position $i$ ($1\le i\le n$), let's count how many triplets $(l, k, r)$ satisfy $(*)$ and $min(a[k+1..r]) = a_i$. It means that $k$ must be the closest position to the left of $i$ satisfying $a_k \lt a_i$. Denotes $x$ as the closest position to the left of $k$ such that $a_x \gt a_i$, and $y$ as the closest position to the right of $i$ such that $a_y \lt a_i$.

We can see that a triplet $(l, k, r)$ with $x \lt l\le k$ and $i\le r \lt y$ will match our condition. In other words, we will add to the answer $(k - x) \cdot (y - i)$.

In the easy version, we can find such values of $x, k, y$ for each $i$ in $\mathcal{O}(n)$ and end up with a total complexity of $O(n^2)$. We can further optimize the algorithm by using sparse table and binary lifting and achieve a time complexity of $\mathcal{O}(n \log{n})$, which is enough to solve the hard version.

There is an $\mathcal{O}(n)$ solution described here.

**Implementation 1**

```
#include <bits/stdc++.h>

using namespace std;

const int N = 500005;
const int LOG = 19;

int a[N], r[N], rmq[LOG][N];

void solve {
  int n; cin >> n;
  long long res = 0;
  vector<int> s;
  a[0] = a[n + 1] = 0;
  for (int i = 1; i <= n; i++) {
    cin >> a[i];
    rmq[0][i] = a[i];
    res += 1ll * i * (i - 1) / 2;
  }
  s.push_back(n + 1);
  for (int i = n; i > 0; i--) {
    while (a[s.back] > a[i])
      s.pop_back;
    r[i] = s.back;
    s.push_back(i);
  }
  for (int k = 1; k < LOG; k++)
    for (int i = (1 << k); i <= n; i++)
      rmq[k][i] = max(rmq[k - 1][i], rmq[k - 1][i - (1 << (k - 1))]);
  s.clear;
  s.push_back(0);
  for (int i = 1; i <= n; i++) {
    while (a[s.back] > a[i])
      s.pop_back;
    int j = s.back;
    for (int k = LOG - 1; k >= 0; k--)
      if (j >= (1 << k) && rmq[k][j] < a[i])
        j -= 1 << k;
    res -= 1ll * (r[i] - i) * (s.back - j);
    s.push_back(i);
  }
  cout << res << '\n';
}

int main {
  cin.tie(0)->sync_with_stdio(0);
  int t; cin >> t;
  while (t--) solve;
}
```

