#include<bits/stdc++.h>

using namespace std;

using ll = long long;

int main {
    ios::sync_with_stdio(false), cin.tie(nullptr);

    ll t;
    cin >> t;

    while (t--) {
        ll n, m;
        cin >> n >> m;

        ll hi = 0, sec_hi = 0;
        for (ll p = (1LL<<62); p > 0; p >>= 1) {
            if (p & n) {
                if (!hi) hi = p;
                else if (!sec_hi) sec_hi = p;
            }
        }
        bool flag = (sec_hi && ((m & hi) || (m < sec_hi*2)));
        if (!flag) {
            cout << -1 << '\n';
            continue;
        }
        vector<ll> ans = {n, m};
        if (!(m & hi) && !(m & sec_hi)) ans = {n, m^sec_hi, m};

        cout << (ll)ans.size-1 << '\n';
        for (auto &x: ans) cout << x << ' ';
        cout << '\n';
    }
    return 0;
}
```

