      d[s] = 0;
      queue<int> Q;
      Q.push(s);
      while (!Q.empty){
        int v = Q.front;
        Q.pop;
        for (int w : E[v]){
          if (d[w] == -1){
            d[w] = d[v] + 1;
            Q.push(w);
