ll n = 0, m = 0, a[3][N] = {}, b[3][N] = {}, c[N] = {}, d[N] = {};
char s[N] = {}, t[N] = {};

inline ll work(ll L, ll R, ll l, ll r){
	ll M = 1; while(M < R - L + r - l) M <<= 1;
	w[0] = 1;
	for(ll k = 1 ; k < M ; k <<= 1){
		ll bit = M / 2 / k;
