B. Seating in a Bus

The key observation is that all occupied seats must form a contiguous segment. Each new passenger must sit adjacent to the current leftmost or rightmost occupied seat. We track the left and right boundaries of the occupied segment and verify each new passenger extends one of the boundaries by exactly one.

```cpp
#include <bits/stdc++.h>
using namespace std;
void solve{
    int n;
    cin >> n;
    vector<int>a(n);
    for(auto &i : a) cin >> i;
    int left = a[0], right = a[0];
    for(int i = 1; i < n; i++){
        if(a[i] + 1 == left) left = a[i];
        else if(a[i] - 1 == right) right = a[i];
        else {
            cout << "NO\n";
            return;
        }
    }
    cout << "YES\n";
}

int main{
    int t;
    cin >> t;
    while (t--) {
        solve;
    }
    return 0;
}
```

C. Numeric String Template

For each string, we maintain two maps: one from characters to array values, and one from array values to characters. For each position, we check that the character-to-value and value-to-character mappings are consistent (bijection). If any contradiction is found, the answer is NO.

```python
def solve:
    n = int(input)
    a = list(map(int, input.split))
    m = int(input)
    for _ in range(m):
        m_1 = {}
        m_2 = {}
        s = input.strip
        if len(s) != n:
            print("NO")
            continue

        ok = True
        for j in range(n):
            if s[j] not in m_1 and a[j] not in m_2:
                m_1[s[j]] = a[j]
                m_2[a[j]] = s[j]
            elif (s[j] in m_1 and m_1[s[j]] != a[j]) or (a[j] in m_2 and m_2[a[j]] != s[j]):
                ok = False
                break
        print("YES" if ok else "NO")

t = int(input)
for _ in range(t):
    solve
```

E. Photoshoot for Gorillas

For each cell $(i, j)$ in the grid, compute how many $k \times k$ sub-squares contain it. This count is $(\min(i, n-k) - \max(-1, i-k)) \times (\min(j, m-k) - \max(-1, j-k))$. To maximize the total spectacle, assign the tallest gorillas to the cells with the highest coverage counts. Sort both the gorilla heights and the coverage counts in descending order, then pair them greedily.

```cpp
#include <bits/stdc++.h>

#define int long long

using namespace std;

#define MAXW 200200
#define MAXNM 200200

int n, m, k, w, p;
int arr[MAXW], prr[MAXNM];

static inline int calcc(int i, int j) {
    int upr = min(i, n - k);
    int leftr = min(j, m - k);
    int upl = max(-1LL, i - k);
    int leftl = max(-1LL, j - k);
    return (upr - upl) * (leftr - leftl);
}

void build {
    sort(arr, arr + w);
    reverse(arr, arr + w);
    p = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            prr[p++] = calcc(i, j);
    sort(prr, prr + p);
    reverse(prr, prr + p);
}

int solve {
    int sum = 0;
    for (int i = 0; i < w; ++i)
        sum += prr[i] * arr[i];
    return sum;
}

signed main {
    int t; cin >> t;
    while (t--) {
        cin >> n >> m >> k >> w;
        for (int i = 0; i < w; ++i)
            cin >> arr[i];
        build;
        cout << solve << endl;
    }
}
```

F. Color Rows and Columns

For each rectangle of width $a$ and height $b$, we can precompute for each number of points $j$ earned from that rectangle, the minimum number of operations needed. The points earned from a rectangle equal the number of completely filled rows plus completely filled columns. We use DP: $dp[i][j]$ = minimum operations to earn exactly $j$ points using the first $i$ rectangles.

For a single rectangle of dimensions $x \times y$, to earn $j$ points we optimally fill whole columns (or rows). If we decide to fill $c$ columns completely, each costs $y$ operations, and similarly for rows. The greedy approach is: always reduce the larger dimension first — each point costs $\min(x, y)$ operations (since completing a column costs $y$ operations and completing a row costs $x$ operations; we always prefer the cheaper direction). The cost array for a single rectangle is built by iterating and reducing the larger of $x$, $y$ at each step.

```cpp
#include <iostream>
#include <algorithm>
#include <vector>

using namespace std;

void solve {
    int n, k;
    cin >> n >> k;
    vector<int> a(n), b(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i] >> b[i];
    }
    vector<vector<int>> dp(n + 1, vector<int>(k + 1, 1e9));
    dp[0][0] = 0;
    for (int i = 0; i < n; ++i) {
        int x = a[i], y = b[i];
        int xy = x + y;
        int cost = 0;
        for (int j = 0; j <= xy; ++j) {
            for (int j1 = 0; j1 + j <= k; ++j1) {
                dp[i + 1][j1 + j] = min(dp[i + 1][j1 + j], dp[i][j1] + cost);
            }
            if (j < xy) {
                if (x >= y) {
                    x--, cost += y;
                } else {
                    y--, cost += x;
                }
            }
        }
    }
    cout << (dp[n][k] == 1e9 ? -1 : dp[n][k]) << '\n';
}

int main {
    int t;
    cin >> t;
    for (int i = 0; i < t; ++i) {
        solve;
    }
    return 0;
}
```

G. Call During the Journey

We run a modified Dijkstra from node $n$ backwards (reverse graph), computing for each node the latest time you can be there and still reach node $n$ by time $t_0$.

For each edge $(u, v)$ with bus time $l_1$ and walking time $l_2$: if you are at node $u$ at time $d$ (meaning you need to depart by time $d$), then to travel to $v$ you can take the bus if the entire bus trip $[d - l_1, d]$ does not overlap the call $[t_1, t_2]$, i.e., $d - l_1 \ge t_2$ or $d \le t_1$. Otherwise you must walk, arriving at time $d - l_2$. Additionally, even when forced to walk, you might wait until after the call ends at $t_2$ and then take the bus: depart at time $t_1$ by bus, giving arrival time $t_1 - l_1$.

The modified transition: given current best time $d$ at node $u$:
- $d_1 = d - l_1$ if $d - l_1 \ge t_2$ or $d \le t_1$, else $d - l_2$
- Also consider $\max(d_1, t_1 - l_1)$ when walking is used

We use a max-priority queue (set) and relax in order of decreasing time.

```cpp
#include <iostream>
#include <vector>
#include <set>

using namespace std;

void solve {
    int n, m;
    cin >> n >> m;
    int t0, t1, t2;
    cin >> t0 >> t1 >> t2;
    vector<vector<vector<int>>> g(n);
    for (int i = 0; i < m; ++i) {
        int u, v, l1, l2;
        cin >> u >> v >> l1 >> l2;
        u--, v--;
        g[u].push_back({v, l1, l2});
        g[v].push_back({u, l1, l2});
    }
    set<pair<int, int>> prq;
    prq.insert({t0, n - 1});
    for (int i = 0; i + 1 < n; ++i) {
        prq.insert({-1e9, i});
    }
    vector<int> dist(n, -1e9);
    dist[n - 1] = t0;
    while (!prq.empty) {
        auto p = *prq.rbegin;
        prq.erase(p);
        int d = p.first, u = p.second;
        for (auto e: g[u]) {
            int v = e[0], l1 = e[1], l2 = e[2];
            int d1 = (d - l1 >= t2 || d <= t1) ? d - l1 : d - l2;
            if(d1 == d - l2) d1 = max(d1, t1 - l1);
            if (dist[v] < d1) {
                prq.erase({dist[v], v});
                dist[v] = d1;
                prq.insert({d1, v});
            }
        }
    }
    cout << (dist[0] >= 0 ? dist[0] : -1) << '\n';
}

int main {
    int t;
    cin >> t;
    for (int i = 0; i < t; ++i) {
        solve;
    }
    return 0;
}
```

H. Ksyusha and the Loaded Set

We maintain a set of "free segments" — maximal contiguous ranges $[l, r)$ not containing any element from our set $M$. Each such segment is stored as a pair $(\text{length}, l)$ in an implicit treap (randomized BST) ordered by these pairs, with each node also storing the minimum $l$ value in its subtree (among segments with length $\ge$ some threshold).

For a query $?k$: we need the minimum $d$ such that $d, d+1, \ldots, d+k-1$ are all absent from $M$. This means we need a free segment of length $\ge k$. We split the treap by key $(k, -1)$ — all segments with length $\ge k$ go to the right part. The answer is the minimum starting position among those segments (given by `minl` of the right part), but we also consider $\max(M) + 1$ as a candidate (since the infinite tail after the last element of $M$ is always free).

For insertion of $x$: find the neighboring elements in $M$ (closest left $clsl$ and closest right $clsr$). Remove the free segment $[clsl+1, clsr)$ and add two new segments $[clsl+1, x)$ and $[x+1, clsr)$.

For deletion of $x$: find neighbors $clsl$ and $clsr$ in $M$ after removing $x$. Remove segments $[clsl+1, x)$ and $[x+1, clsr)$, add merged segment $[clsl+1, clsr)$.

```cpp
#pragma GCC optimize("O3,unroll-loops")

#include <bits/stdc++.h>

#define endl '\n'

using namespace std;

typedef pair<int, int> ipair;

#define INF 1'000'000'009
#define MAXN 200200
#define MAXMEM 5'000'000
#define MAXLEN 2'000'100

#define X first
#define Y second

mt19937 rng(chrono::steady_clock::now.time_since_epoch.count);

struct node {
    node *lv = nullptr, *rv = nullptr;
    ipair key;
    int prior;
    int minl = INF;

    node(const ipair& key) : key(key), prior(rng), minl(key.Y) {}
};

static inline int minl(node *v) {
    return (v == nullptr ? INF : v->minl);
}

static inline void upd(node *v) {
    v->minl = min(v->key.Y, min(minl(v->lv), minl(v->rv)));
}

node *merge(node *s1, node *s2) {
    if (s1 == nullptr) return s2;
    if (s2 == nullptr) return s1;
    if (s1->prior > s2->prior) {
        s1->rv = merge(s1->rv, s2);
        return s1;
    } else {
        s2->lv = merge(s1, s2->lv);
        return s2;
    }
}

pair<node*, node*> split(node* &v, ipair x) {
    if (v == nullptr) {
        return {nullptr, nullptr};
    }
    if (v->key < x) {
        auto [s1, s2] = split(v->rv, x);
        v->rv = s1;
        return {v, s2};
    } else {
        auto [s1, s2] = split(v->lv, x);
        v->lv = s2;
        return {s1, v};
    }
}

int n, m;
int arr[MAXN];
node *mem = (node*)calloc(MAXMEM, sizeof(*mem));
node *mpos = mem;
node *root;
set<int> M;

// [l..r)
void add_seg(int l, int r) {
    if (l >= r) return;
    ipair p {r - l, l};
    auto [s1, s2] = split(root, p);
    node *v = mpos++;
    *v = node(p);
    root = merge(merge(s1, v), s2);
}

void rem_dek(node* &v, const ipair& x) {
    if (v == nullptr) return;
    if (v->key == x) {
        v = merge(v->lv, v->rv);
        if (v) upd(v);
        return;
    }
    if (v->key < x) rem_dek(v->rv, x);
    else rem_dek(v->lv, x);
}

// [l..r)
void rem_seg(int l, int r) {
    if (l >= r) return;
    ipair p {r - l, l};
    rem_dek(root, p);
}

void add_val(int x) {
    auto it = M.lower_bound(x);
    int clsl = (it == M.begin ? 0 : *prev(it));
    int clsr = (it == M.end ? INF : *it);
    rem_seg(clsl + 1, clsr);
    add_seg(clsl + 1, x);
    if (clsr != INF) add_seg(x + 1, clsr);
    M.insert(x);
}

void rem_val(int x) {
    auto it = M.lower_bound(x);
    int clsl = (it == M.begin ? 0 : *prev(it));
    int clsr = (next(it) == M.end ? INF : *next(it));
    rem_seg(clsl + 1, x);
    rem_seg(x + 1, clsr);
    if (clsr != INF) add_seg(clsl + 1, clsr);
    M.erase(x);
}

int query(int k) {
    if (M.empty) return 1;
    auto [s1, s2] = split(root, make_pair(k, -1));
    int ans = min(*M.rbegin + 1, minl(s2));
    root = merge(s1, s2);
    return ans;
}

void init {
    root = nullptr;
    mpos = mem;
    M = {arr, arr + n};
    add_seg(1, *M.begin);
    for (auto it = M.begin; next(it) != M.end; ++it)
        add_seg(*it + 1, *next(it));
}

signed main {
    int t; cin >> t;
    while (t--) {
        cin >> n;
        for (int i = 0; i < n; ++i)
            cin >> arr[i];
        init;
        cin >> m;
        for (int j = 0; j < m; ++j) {
            char tp; cin >> tp;
            int x, k;
            switch (tp) {
            case '+':
                cin >> x;
                add_val(x);
                break;
            case '-':
                cin >> x;
                rem_val(x);
                break;
            case '?':
                cin >> k;
                cout << query(k) << " ";
                break;
            }
        }
        cout << endl;
    }
}
```

It can be shown that for any $k\times k$ subgrid, the colors we use must be pairwise distinct. Thus, we have an lower bound of $\min(n,k)\cdot\min(m,k)$. We can show that this lower bound is indeed achievable by coloring the upper-left $\min(n,k)\cdot\min(m,k)$ subgrid with distinct colors, and copy-pasting it to fill the rest of the grid.

