    segtree : segtree(-1, -1) {};
    segtree(int l, int r) : l(l), r(r) {
        if (l == r) return;
        int m = (l + r) / 2;
        lc = getmem; *lc = segtree(l, m);
        rc = getmem; *rc = segtree(m + 1, r);
    }
    int op(int a, int b) {
        return min(a,b);
    }
    int op2(int a, int b) {
        return a+b;
