C. Sakurako's Field Trip

The operation swaps $a[i]$ and $a[n-i+1]$. Process pairs from the inside out (i.e., from $i = n/2 - 1$ down to $1$). For each pair of positions $(i, i+1)$ and $(n-i, n-i+1)$, if either adjacent pair has equal elements, perform the swap to try to fix it. After processing all such swaps, count the remaining disturbances.

```cpp
#include <bits/stdc++.h>
using namespace std;
int main{
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        int a[n+1];
        for(int i=1;i<=n;i++){
            cin>>a[i];
        }
        for(int i=n/2-1;i>=1;i--){
            if(a[i]==a[i+1] || a[n-i+1]==a[n-i]){
                swap(a[i],a[n-i+1]);
            }
        }
        int re=0;
        for(int i=1;i<n;i++){
            re+=(a[i]==a[i+1]);
        }
        cout<<re<<endl;
    }
}
```

D. Kousuke's Assignment

Use prefix sums. A segment $[l, r]$ has sum $0$ iff $\text{prefix}[r] = \text{prefix}[l-1]$. For each position $i$, find the most recent previous position $\text{lst}[i]$ where the prefix sum equals $\text{prefix}[i]$. Then use DP: $dp[i] = \max(dp[i-1], dp[\text{lst}[i]] + 1)$ if $\text{lst}[i]$ exists, otherwise $dp[i] = dp[i-1]$.

```cpp
#include <bits/stdc++.h>
using namespace std;
int main{
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        int a[n+1];
        map<int,int>mp;
        for(int i=1;i<=n;i++){
            cin>>a[i];
        }
        int p_su[n+1];
        p_su[0]=0;
        int lst[n+1];
        mp[0]=0;
        for(int i=1;i<=n;i++){
            p_su[i]=p_su[i-1]+a[i];
            if(mp.find(p_su[i])==mp.end){
                lst[i]=-1;
            }
            else{
                lst[i]=mp[p_su[i]];
            }
            mp[p_su[i]]=i;
        }
        int dp[n+1];
        memset(dp,0,sizeof dp);
        for(int i=1;i<=n;i++){
            dp[i]=max(dp[i],dp[i-1]);
            if(lst[i]!=-1){
                dp[i]=max(dp[i],dp[lst[i]]+1);
            }
        }
        cout<<*max_element(dp,dp+n+1)<<endl;
    }
}
