**Solution**

Sort all edges by weight. Build a sequence of distance matrices, but only for MST (Kruskal) edges — there are at most $n-1$ of them. We keep $n$ matrices $\text{dis}[0], \ldots, \text{dis}[n-1]$, where $\text{dis}[p][i][j]$ is the minimum number of edges with weight $> \text{value}[p]$ on any path from $i$ to $j$.

- $\text{dis}[0]$ is computed by Floyd-Warshall on the unweighted graph (each edge has weight 1).
- For each new MST edge $(v, u, w)$ added in sorted order (using DSU to skip non-MST edges), update: $\text{dis}[p][i][j] = \min(\text{dis}[p-1][i][j],\ \text{dis}[p-1][i][v] + \text{dis}[p-1][u][j],\ \text{dis}[p-1][i][u] + \text{dis}[p-1][v][j])$.

For a query $(a, b, k)$, binary search on $p$: find the smallest $p$ such that $\text{dis}[p][a][b] < k$. The answer is $\text{value}[p]$.

The key insight is that only MST edges matter for the optimal path structure — specifically, the path that minimizes the $k$-th maximum edge weight uses only MST edges. Since $m$ can be up to $O(n^2)$ but we only store $n$ matrices, memory is $O(n^3)$.

**Implementation**

```cpp
#include <bits/stdc++.h>

using i64 = long long;

struct DSU {
    std::vector<int> p, sz, h;

    DSU(int n = 0) : p(n), sz(n, 1), h(n) {
        std::iota(p.begin, p.end, 0);
    }

    int leader(int x) {
        if (x == p[x]) {
            return x;
        }
        return leader(p[x]);
    }

    bool same(int x, int y) {
        return leader(x) == leader(y);
    }

    bool merge(int x, int y) {
        x = leader(x);
        y = leader(y);
        if (x == y) return false;
        if (h[x] < h[y]) {
            std::swap(x, y);
        }
        if (h[x] == h[y]) {
            ++h[x];
        }
        sz[x] += sz[y];
        p[y] = x;
        return true;
    }

    int size(int x) {
        return sz[leader(x)];
    }
};

void solve {
    int n, m, q;
    std::cin >> n >> m >> q;
    std::vector<std::array<int, 3>> edges(m);
    for (int i = 0; i < m; i++) {
        int v, u, w;
        std::cin >> v >> u >> w;
        v--, u--;
        edges[i] = {v, u, w};
    }
    std::sort(edges.begin, edges.end, [&](const std::array<int, 3> &a, const std::array<int, 3> &b) {
        return a[2] < b[2];
    });
    constexpr int INF = 1e9;
    std::vector<int> value(n);
    std::vector<std::vector<std::vector<int>>> dis(n, std::vector<std::vector<int>>(n, std::vector<int>(n, INF)));
    for (int i = 0; i < n; i++) {
        dis[0][i][i] = 0;
    }
    for (auto edge : edges) {
        int v = edge[0], u = edge[1];
        dis[0][v][u] = dis[0][u][v] = 1;
    }
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dis[0][i][j] = std::min(dis[0][i][j], dis[0][i][k] + dis[0][k][j]);
            }
        }
    }
    int p = 1;
    DSU dsu(n);
    for (auto edge : edges) {
        int v = edge[0], u = edge[1], w = edge[2];
        if (dsu.merge(v, u)) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    dis[p][i][j] = std::min({dis[p - 1][i][j], dis[p - 1][i][v] + dis[p - 1][u][j], dis[p - 1][i][u] + dis[p - 1][v][j]});
                }
            }
            value[p++] = w;
        }
    }
    for (int i = 0; i < q; i++) {
        int v, u, k;
        std::cin >> v >> u >> k;
        v--, u--;
        int low = 0, high = n - 1;
        while (high - low > 1) {
            int mid = (low + high) / 2;
            if (dis[mid][v][u] < k) {
                high = mid;
            } else {
                low = mid;
            }
        }
        std::cout << value[high] << " \n"[i == q - 1];
    }
}

