**Alternative solution**

```cpp
// Parallel binary search technique optimizes log^3 => log^2
// SegmentTree might be faster then std::multiset
// sl[i] should equals max(a) at the begining cause IDK how to explain but it's obviously important

#include <bits/stdc++.h>
#include <algorithm>

using namespace std;
using ll = long long;

constexpr int W = 31;
constexpr int C = 1'000'000'000;

struct Event {
    int x;
    int ind;
    ll s;

    bool operator<(const Event& rhs) const { return x < rhs.x; }
};

struct SegmentTree {
    int n;
    vector<ll> sgt;

    SegmentTree(int n) : n(n), sgt(2 * n, -1) {}

    void Change(int i, ll x) {
        for (sgt[i += n] = x; i != 1; i >>= 1) {
            sgt[i >> 1] = max(sgt[i], sgt[i ^ 1]);
        }
    }

    int GlobalMax const { return sgt[1]; }
};

vector<int> solve(const vector<int>& a, const vector<int>& q) {
    const int n = a.size, m = q.size;

    vector<ll> ps(n + 1);
    for (int i = 0; i < n; ++i)
        ps[i + 1] = ps[i] + a[i];

    vector<ll> min_x(n, 0);
    vector<vector<pair<int, ll>>> change_sum(W);

    vector<Event> events;
    events.reserve(2 * n);
    for (int j = 1; j <= W && j <= n; ++j) {
        events.clear;

        for (int i = j - 1; i < n; ++i) {
            min_x[i] = max(min_x[i], 1 + ((a[i - j + 1] - 1ll) << (j - 1)));
            ll max_x = i == j - 1 ? 2ll * C : ((ll)a[i - j] << j);
            max_x = min<ll>(max_x, a[i] + C);

            if (min_x[i] > max_x) {
                continue;
            }
            const ll xsum = ps[i + 1] - ps[i + 1 - j];
            events.push_back(Event{(int)min_x[i], i, xsum});
            events.push_back(Event{(int)max_x + 1, i, -1});
        }
        sort(events.begin, events.end);

        SegmentTree sgt(n);
        const int k = events.size;
        ll was_max = -1;

        for (int i = 0; i < k;) {
            int s = i;
            while (i < k && events[i].x == events[s].x) {
                sgt.Change(events[i].ind, events[i].s);
                ++i;
            }
            ll cur_max = sgt.GlobalMax;
            if (cur_max != was_max) {
                change_sum[j - 1].emplace_back(events[s].x, cur_max);
                was_max = cur_max;
            }
        }
    }

    vector<int> sl(m, *max_element(a.begin, a.end)), sr(m, 2 * C + 1);

    vector<int> ord_to_check(m);
    iota(ord_to_check.begin, ord_to_check.end, 0);
    for (int iter = 32; iter--;) {
        vector<int> sm(m);
        for (int i = 0; i < m; ++i) {
            sm[i] = sl[i] + (sr[i] - sl[i]) / 2;
        }
        sort(ord_to_check.begin, ord_to_check.end, [&](int lhs, int rhs) {
            return sm[lhs] < sm[rhs];
        });

        vector<int> ptr(W);
        vector<ll> actual_sum(W, -1);
        for (int i : ord_to_check) {
            const int x = sm[i];

            ll upper_sum = 0;
            bool nice = false;
            for (int w = 0; w < W; ++w) {
                int& j = ptr[w];
                while (j < change_sum[w].size && change_sum[w][j].first <= x) {
                    actual_sum[w] = change_sum[w][j++].second;
                }
                upper_sum += 1 + ((x - 1) >> w);
                if (upper_sum - actual_sum[w] <= q[i]) {
                    nice = true;
                }
            }

            if (nice) {
                sl[i] = sm[i];
            } else {
                sr[i] = sm[i];
            }
        }
    }

    return sl;
}

int main {
    ios::sync_with_stdio(0);
    cin.tie(0);

    int t = 1;
    cin >> t;
    while (t--) {
        int n, q;
        cin >> n >> q;
        vector<int> a(n), k(q);
        for (int& x : a)
            cin >> x;
        for (int& x : k)
            cin >> x;

        auto ans = solve(a, k);
        for (int x : ans)
            cout << x << ' ';
        cout << '\n';
    }
}
```

output_format:
For each test case, output $$$n$$$ lines consisting of $$$m$$$ symbols, where each symbol encodes the state of the cell:

•  "#" — the cell is in $$$A$$$ but not in $$$S$$$;
•  "S" — the cell is in both $$$A$$$ and $$$S$$$;
•  "." — the cell is neither in $$$A$$$ nor in $$$S$$$.

editorial_cleaned:
**Solution**

Color each cell $(i, j)$ (0-indexed) with color $(i + 2j) \bmod 5$. For each free cell, add it to the coloring bucket of its own color, and also add it to the coloring bucket of each neighbor's color (for neighbors that are non-free or out-of-bounds). Among the 5 colorings, choose the one with the fewest cells and mark those cells as $S$.

This works because $|S| \le \frac{1}{5}(s + p)$: each free cell contributes 1 to some coloring's count (for itself), and each boundary edge of the free region contributes 1 to some coloring's count (for the adjacent free cell). There are $s$ free cells and $p$ boundary contributions total, so by pigeonhole the minimum coloring has at most $\frac{s+p}{5}$ cells.

Coverage holds because any two adjacent free cells have different colors (since $(i+2j) \bmod 5$ differs by $\pm 1$ or $\pm 2$ for horizontal/vertical neighbors, and since $\gcd(1,5)=\gcd(2,5)=1$, all 5 colors appear in any $1\times 5$ or $5\times 1$ strip), so every free cell either is in $S$ or has a neighbor in $S$.

**Implementation**

```cpp
#include <bits/stdc++.h>

using namespace std;
using pi = pair<int, int>;

void solve {
    int n, m; cin >> n >> m;
    vector<string> v(n);
    for (auto& w : v) cin >> w;

    auto col = (int x, int y) {
        int c = (x+2*y)%5;
        if (c < 0) c += 5;
        return c;
    };
    auto cell = [&](int x, int y) {
        if (x < 0 || y < 0 || x >= n || y >= m) return false;
        return v[x][y] == '#';
    };

    array<vector<pi>, 5> colorings;
    for (int i = 0; i < n; ++i)
    for (int j = 0; j < m; ++j) {
        if (!cell(i, j)) continue;
        colorings[col(i, j)].emplace_back(i, j);

        for (int di = -1; di <= 1; ++di)
        for (int dj = -1; dj <= 1; ++dj) {
            if (abs(di) + abs(dj) != 1) continue;
            if (!cell(i+di, j+dj)) {
                colorings[col(i+di, j+dj)].emplace_back(i, j);
            }
        }
    }

    auto coloring = colorings[0];
    for (const auto& w : colorings)
        if (w.size < coloring.size) coloring = w;
    for (auto [x, y] : coloring) v[x][y] = 'S';
    for (auto line : v) cout << line << '\n';
}

int main {
    ios::sync_with_stdio(0); cin.tie(0);

    int t; cin >> t;
    while (t--)
        solve;
}
```

**Solution**

For each position $i$, compute the maximum number of students that can flow into position $i$ from the left (call it $\text{lhs}[i]$) and from the right (call it $\text{rhs}[i+1]$). The answer for position $i$ is $a_i + \text{lhs}[i] + \text{rhs}[i+1]$.

To compute `get_right_out` (how much flows to the right boundary of each prefix): process positions left to right. Maintain a stack of "wave fronts". When processing position $i$ with $x = a[i] + \text{res}[i]$ students incoming, repeatedly merge with the stack:
- If the stack is empty, the wave from position 0 to $i$ (length $\ell = i+1$) can drain $\lfloor x / (\ell+1) \rfloor$ full cycles, each sending $\ell$ students to position $i+1$. Then handle the remainder.
- Otherwise, look at the top of the stack (representing a wave starting at position $j$): if $x > i - j$, pop and subtract $i - j + 1$ from $x$, sending $i - j$ to position $i+1$; otherwise send $x$ students right and update the stack top.

For `get_left_out`, reverse the array, apply `get_right_out`, then reverse back.

**Implementation**

```cpp
#include <bits/stdc++.h>

using namespace std;
using vi = vector<int>;
using ll = long long;

vector<ll> a, lhs, rhs;
vector<int> st;

vector<ll> get_right_out(const vector<ll>& a, vector<ll>& res) {
    const int n = a.size;
    st.clear;
    res.assign(n+1, 0);

    for (int i = 0; i < n; ++i) {
        ll x = a[i] + res[i];
        st.push_back(i);

        while (x != 0) {
            if (st.empty) {
                const int len = i + 1;
                const ll cnt = x / (len + 1);
                res[i+1] += cnt * len;
                x -= cnt * (len + 1);

                if (x != 0) {
                    res[i+1] += x;
                    st.push_back(x-1);
                    x = 0;
                }
            } else {
                const int j = st.back;
                if (x > i - j) {
                    res[i+1] += i - j;
                    st.pop_back;
                    x -= i - j + 1;
                } else {
                    res[i+1] += x;
                    st.back += x;
                    x = 0;
                }
            }
        }
    }

    return res;
}

vector<ll> get_left_out(vector<ll>& a, vector<ll>& b) {
    reverse(a.begin, a.end);
    get_right_out(a, b);
    reverse(b.begin, b.end);
    reverse(a.begin, a.end);
    return b;
}

