            int T = Read<int>;
            while (T-- > 0)
            {
                int k = Read<int>, n = Read<int>;
                if (n <= bw) {
                    for (int j = 1; j <= k; ++j) output.Append(S[n, j]).Append(' ');
                } else {
                    int _k = k;
                    for (k = 1; k <= _k; ++k)  {
                        long ans = 0;
                        for (int i = 1; i <= bw; ++i) {
                            long t = S[i, k];
                            for (int j = 1; j <= bw; ++j) {
                                if (j == i) continue;
                                t *= n - j;
                                t %= mod;
                                t *= Inv((mod + i - j) % mod, mod);
                                t %= mod;
                            }
                            ans = (ans + t) % mod;
                        }
                        output.Append(ans).Append(' ');
                    }
                }
                output.AppendLine;
            }
            Console.Write(output.ToString);
        }
        public static long Inv(long a, long Mod) {
            long u = 0, v = 1, m = Mod;
            while (a > 0) {
                long t = m / a;
                m -= t * a; (a, m) = (m, a);
                u -= t * v; (u, v) = (v, u);
            }
            return (u % Mod + Mod) % Mod;
        }
    }
