For convenience, assume $n$ is odd (if not, increment $n$ and handle the edge case separately). Start by precomputing the first $2n$ terms $a_1, a_2, \ldots, a_{2n}$. For queries with indices less than or equal to $2n$, directly return the precomputed value. For $2m \gt n$, observe the following relationship

 $ a_{2m} = a_1 \oplus a_2 \oplus \ldots \oplus a_m = a_{2m + 1}. $

Define $p = a_1 \oplus a_2 \oplus \ldots \oplus a_n$. Notice that when $m \gt n$, we can decompose the XOR sum as:

 $ {} $ $ a_{2m} = a_1 \oplus a_2 \oplus \ldots \oplus a_m = a_1 \oplus a_2 \oplus \ldots \oplus a_n \oplus (a_{n + 1} \oplus a_{n + 2}) \oplus (a_{n + 3} \oplus a_{n + 4}) \oplus \ldots \oplus a_m $ $ a_{2m} = p \oplus (a_{n + 1} \oplus a_{n + 2}) \oplus (a_{n + 3} \oplus a_{n + 4}) \oplus \ldots \oplus a_m $

Since $n$ is odd, the pairs $(a_{n + 1} \oplus a_{n + 2}), (a_{n + 3} \oplus a_{n + 4}), \ldots$ cancel out. This simplifies the formula to:

 $ {} $ $ a_{2m} = a_{2m + 1} = \begin{cases} p & \text{if } m \text{ is odd}, \\ p \oplus a_m & \text{if } m \text{ is even}. \end{cases} $

As a result, we can compute $a_m$ recursively by halving $m$ until $m \le 2n$, applying the parity rule at each step.

The overall time complexity is: $O(n+\log(m))$.

```
#include<bits/stdc++.h>
using namespace std;
void solve {
    int n;
    int64_t l, r;
    cin >> n >> l >> r;
    vector<int> a(n + 1);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    vector<int> pref(n + 1);
    for (int i = 1; i <= n; i++) {
        pref[i] = pref[i - 1] + a[i];
    }
    if (n % 2 == 0) {
        n++;
        int cur = pref[n / 2] & 1;
        a.push_back(cur);
        pref.push_back(pref.back + cur);
    }
    for (int i = n + 1; i <= n * 2; i++) {
        a.push_back(pref[i / 2] & 1);
        pref.push_back(pref[i - 1] + a[i]);
    }
    int p = pref[n] & 1;
    auto get = [&](int64_t x) {
        int ret = 0;
        while (true) {
            if (x <= n * 2) {
                ret ^= a[x];
                break;
            }
            ret ^= p;
            if ((x / 2 - n) % 2 == 0) {
                break;
            }
            x /= 2;
        }
        return ret;
    };
    cout << get(l) << "\n";
}
int main {
    ios::sync_with_stdio(0), cin.tie(0);
    int tt = 1;
    cin >> tt;
    while (tt--) {
        solve;
    }
}
