We want to construct an array of length $n$ whose OR equals $x$ and whose MEX is maximized. Greedily assign $a_i = i$ for $i = 0, 1, \ldots, n-2$ as long as $(\text{or\_val} \mid i) \subseteq x$ (i.e., $((\text{or\_val} | i) \& x) == (\text{or\_val} | i)$), accumulating the OR. Set the last element to $x$ (or $n-1$ if possible) to ensure the OR equals $x$.

```cpp
#include <iostream>
#include <vector>

using namespace std;

void Solve {
  int len, val;
  cin >> len >> val;
  vector<int> ans(len, val);
  int or_val = 0;
  bool flag = true;
  for (int i = 0; i < len - 1; ++i) {
    if (((or_val | i) & val) == (or_val | i)) {
      or_val |= i;
      ans[i] = i;
    } else {
      flag = false;
      break;
    }
  }
  if (flag && (or_val | (len - 1)) == val) {
    ans[len - 1] = len - 1;
  }
  for (auto it : ans) cout << it << ' ';
  cout << '\n';
}

signed main {
  cin.tie(0)->sync_with_stdio(0);
  int test_count = 1;
  cin >> test_count;
  while (test_count --> 0) Solve;
}
```

A cyclic left shift of $[l, r]$ moves $a_l$ to position $r$ and shifts everything else left by one. The change in inversions equals: for each $j \in (l, r]$, we lose an inversion if $a_l > a_j$ (previously counted) and gain an inversion if $a_l < a_j$. So the net change in inversions from choosing segment $[l+1, r]$ (0-indexed: $[i, j]$) is $\text{cnt\_greater} - \text{cnt\_less}$ where these count elements in $(i, j]$ greater/less than $a_i$. We iterate over all $O(n^2)$ pairs and pick the one minimizing this difference (we want the most negative change).

```cpp
#include <bits/stdc++.h>

using namespace std;

void solve {
  int n;
  cin >> n;
  vector<int> a(n);
  for (int i = 0; i < n; ++i) {
    cin >> a[i];
  }

  int best_diff = 0, L = 0, R = 0;
  for (int i = 0; i < n; ++i) {
    int cnt_greater = 0, cnt_less = 0;
    for (int j = i + 1; j < n; ++j) {
      cnt_greater += a[j] > a[i];
      cnt_less += a[j] < a[i];

      if (best_diff > cnt_greater - cnt_less) {
        best_diff = cnt_greater - cnt_less;
        L = i, R = j;
      }
    }
  }

  cout << L + 1 << ' ' << R + 1 << '\n';
}

int main {
