Note that $\rho(a,b) = d(a,b)$ iff the two points lie on a horizontal or vertical line (i.e., $x_a = x_b$ or $y_a = y_b$). We need exactly $k$ such pairs.

The idea is to decompose $k$ greedily: find the largest triangular number $T = \delta(\delta-1)/2 \le k$, place $\delta$ points on a horizontal line (contributing $\binom{\delta}{2} = T$ pairs), then recursively handle the remaining $k - T$ pairs in a separate region (offset so no cross-pairs satisfy the condition). This gives a recursive construction.

Since $k \le 10^5$, the maximum $\delta$ is about $450$, and the total number of points is at most $500$.

```cpp
#include <bits/stdc++.h>

using namespace std;

vector<pair<int64_t, int64_t>> rec(int64_t k, int64_t x0 = 0, int64_t y0 = 0) {
  if (!k) {
    return {};
  }
  int64_t delta = 0;
  while (delta * (delta - 1) / 2 <= k) {
    delta++;
  }
  delta--;
  auto remaining = rec(k - delta * (delta - 1) / 2, x0 + delta + 1, y0 + 1);
  vector<pair<int64_t, int64_t>> ans;
  for (int x = x0; x < x0 + delta; ++x) {
    ans.push_back({x, y0});
  }
  ans.insert(ans.end, remaining.begin, remaining.end);
  return ans;
}

void solve {
  int64_t k;
  cin >> k;
  if (!k) {
    cout << "1\n69 52\n";
    return;
  }
  auto ans = rec(k, 0, 0);
  cout << ans.size << '\n';
  for (auto [x, y] : ans) {
    cout << x << ' ' << y << '\n';
  }
}

int main {
  int tt = 1;
  cin >> tt;
  while (tt --> 0) {
    solve;
  }
  return 0;
}
```

The triangle is essentially Pascal's triangle but with XOR instead of addition. By Lucas' theorem generalized to XOR: $T_{n,j}$ (0-indexed row $n-1$, column $j$) equals $k \cdot \binom{n-1}{j} \bmod 2$. By Kummer's theorem, $\binom{n}{j} \bmod 2 = 1$ iff there are no carries when adding $j$ and $n-j$ in binary, which is equivalent to $v_2(n!) = v_2(j!) + v_2((n-j)!)$ where $v_2$ is the 2-adic valuation (i.e., the number of times 2 divides a number, accumulated as $c[i] = \sum_{m=2}^{i} v_2(m)$). So the $j$-th element of row $n$ is $k$ if $c[n-1] = c[j] + c[n-1-j]$, and $0$ otherwise.

Precompute $c[i]$ as the prefix sum of 2-adic valuations.

```cpp
#include <bits/stdc++.h>

using namespace std;

constexpr int64_t kMaxN = 1e6 + 69;
vector<int64_t> c(kMaxN);

void precalc {
  c[0] = c[1] = 0;
  for (int i = 2; i < kMaxN; ++i) {
    c[i] = c[i - 1];
    int x = i;
    while (x % 2 == 0) {
      x /= 2, c[i]++;
    }
  }
}

void solve {
  int n, k;
  cin >> n >> k;

  --n;
  for (int i = 0; i <= n; ++i) {
    cout << k * (c[n] == c[i] + c[n - i]) << " \n"[i == n];
  }
}

int main {
  ios::sync_with_stdio(0);
  cin.tie(0);

  precalc;

  int tt = 1;
  cin >> tt;
  while (tt --> 0) {
    solve;
  }
  return 0;
}
```

We need to compute $\sum_{p=2}^{k} \text{rev}(n, p) \bmod 10^9+7$.

Key observation: when $p > n$, $n$ is a single digit in base $p$, so $\text{rev}(n, p) = n$. There are $\max(0, k - n)$ such bases (from $n+1$ to $k$), contributing $n \cdot \max(0, k-n)$.

For $p \le n$, note that $\sqrt{n}$ is a threshold: for $p \le \sqrt{n}$, we compute $\text{rev}(n, p)$ directly (brute force), since there are only $O(\sqrt{n})$ such bases.

For $\sqrt{n} < p \le n$, $n$ has at most 2 digits in base $p$ (since $p^2 > n$). Write $n = q \cdot p + r$ where $r = n \bmod p$ and $q = \lfloor n/p \rfloor$. Then $\text{rev}(n, p) = r \cdot p + q$. So the contribution is:
$$\sum_{p=\lfloor\sqrt{n}\rfloor+1}^{\min(n,k)} (n \bmod p) \cdot p + \lfloor n/p \rfloor$$
$$= \sum_p (n - \lfloor n/p \rfloor \cdot p) \cdot p + \lfloor n/p \rfloor = \sum_p n \cdot p - \lfloor n/p \rfloor \cdot p^2 + \lfloor n/p \rfloor$$

Using the standard "divisor sum" trick, we group values of $\lfloor n/p \rfloor$ (which takes $O(\sqrt{n})$ distinct values), and for each group compute the sum of $p$ and $p^2$ using prefix sums (sum of arithmetic series and sum of squares). This gives an $O(\sqrt{n})$ algorithm for this range.

Overall complexity: $O(\sqrt{n})$ per test case.

```cpp
#include <bits/stdc++.h>

using namespace std;

constexpr int64_t mod = 1e9 + 7;
constexpr int64_t twoInv = 500'000'004;
constexpr int64_t sixInv = 166'666'668;

int64_t add(int64_t a, int64_t b) {
  return (a % mod + b % mod) % mod;
}

int64_t mns(int64_t a, int64_t b) {
  return (a % mod - b % mod + mod) % mod;
}

int64_t mul(int64_t a, int64_t b) {
  return (a % mod) * (b % mod) % mod;
}

int64_t rev(int64_t n, int64_t p) {
  int64_t res = 0;
  while (n) {
    res = add(mul(res, p), n % p);
    n /= p;
  }
  return res;
}

int64_t stupid(int64_t n, int64_t k) {
  int64_t res = 0;
  for (int64_t p = 2; p <= k; ++p) {
    res = add(res, rev(n, p));
  }
  return res;
}

int64_t sum1(int64_t r) {
  return mul(mul(r, r + 1), twoInv);
}

int64_t sum1(int64_t l, int64_t r) {
  return mns(sum1(r), sum1(l - 1));
}

int64_t sum2(int64_t r) {
  return mul(mul(mul(r, r + 1), 2 * r + 1), sixInv);
}

int64_t sum2(int64_t l, int64_t r) {
  return mns(sum2(r), sum2(l - 1));
}

int64_t get(int64_t n, int64_t l, int64_t r) {
  if (l > r) {
    return 0;
  }

  int64_t res = mul(sum1(l, r), n);
  int64_t minus = 0, plus = 0;

  int64_t L = l;
  while (L <= r) {
    int64_t value = n / L;
    int64_t R = min(r, n / value);

    minus = add(minus, mul(sum2(L, R), value));
    plus = add(plus, mul(R - L + 1, value));

    L = R + 1;
  }

  return add(mns(res, minus), plus);
}

void solve {
  int64_t n, k;
  cin >> n >> k;

  int64_t sq = (int64_t)sqrtl((long double)n);
  int64_t ans = mul(max<int64_t>(0, k - n), n);
  ans = add(ans, stupid(n, min(sq, k)));
  ans = add(ans, get(n, sq + 1, min(n, k)));

  cout << ans << '\n';
}

int main {
  int tt = 1;
  cin >> tt;
  while (tt --> 0) {
    solve;
  }
  return 0;
}
```

