		if (ask[i]) {
			auto [lf, rg] = seg[i];
			ans = max(ans, 1 + (lf < rg ? 1 + getmax(0) : 0));
		}
		if (added[i]) {
			addToSeg(i, -1);
			added[i] = 0;
		}
	}
	cout << ans << endl;
}

