            for(ull x=p,phi=p-1;x<=B;x*=p,phi*=p)DFS2(x,i+1,phi);
        }
        fprintf(stderr,"case2 done %lf\n",((ed=clock)-st)/1000);st=ed;
        return n*(n+1)/2-sum;
    }
}
