**Hint 1**

Consider the position of the minimum value after rearranging the sequence.

**Hint 2**

What kind of numbers should be placed on the $\min$ side, and what kind should be placed on the $\gcd$ side?

**Solution**

Let $x = \min(a)$. Place $x$ on the $\min$ side. For the $\gcd$ side, we need the gcd of some subset of the remaining elements to equal $x$. So we check if the gcd of all elements divisible by $x$ (excluding $x$ itself) equals $x$. If so, output "Yes", otherwise "No".

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main {
	ios::sync_with_stdio(0);
	cin.tie(0);
	int T, n;
	cin >> T;
	while (T--) {
		cin >> n;
		vector<ll> a(n);
		for (ll &x : a) {
			cin >> x;
		}
		int p = min_element(a.begin, a.end) - a.begin;
		ll g = 0;
		for (int i = 0; i < n; ++i) {
			if (i != p && a[i] % a[p] == 0) {
				g = __gcd(g, a[i]);
			}
		}
		cout << (g == a[p] ? "Yes\n" : "No\n");
	}
	return 0;
}
```

**Hint 1**

Will the $b_i$ corresponding to a given $a_i$ change?

**Hint 2**

Individually place each pair corresponding to $(a_i, b_i)$ (i.e., $(b_i, a_i)$) at position $n - i + 1$.

**Solution**

First, check feasibility: for each $i$, if $a_i = b_i$, this element must go to the middle (only possible when $n$ is odd, and there can be at most one such element). For all other $i$, the pair $(a_i, b_i)$ must satisfy $b[\text{pos of } b_i] = a_i$ (i.e., the pairs must be symmetric). 

Then, if $n$ is odd, move the element where $a_i = b_i$ to position $(n+1)/2$. For positions $1$ to $n/2$, move the element at position $\text{pos}[b_i]$ to position $n-i+1$.

```cpp
#include <bits/stdc++.h>
using namespace std;

const int maxn = 200100;

int n, a[maxn], b[maxn], m, p[maxn], ans[maxn][2];

inline void work(int x, int y) {
	if (x == y) {
		return;
	}
	ans[++m][0] = x;
	ans[m][1] = y;
	swap(a[x], a[y]);
	swap(p[a[x]], p[a[y]]);
	swap(b[x], b[y]);
}

void solve {
	cin >> n;
	for (int i = 1; i <= n; ++i) {
		cin >> a[i];
		p[a[i]] = i;
	}
	for (int i = 1; i <= n; ++i) {
		cin >> b[i];
	}
	m = 0;
	int x = 0;
	for (int i = 1; i <= n; ++i) {
		if (a[i] == b[i]) {
			if (n % 2 == 0 || x) {
				cout << "-1\n";
				return;
			}
			x = i;
		} else if (b[p[b[i]]] != a[i]) {
			cout << "-1\n";
			return;
		}
	}
	if (n & 1) {
		work(x, (n + 1) / 2);
	}
	for (int i = 1; i <= n / 2; ++i) {
		work(p[b[i]], n - i + 1);
	}
	cout << m << '\n';
	for (int i = 1; i <= m; ++i) {
		cout << ans[i][0] << ' ' << ans[i][1] << '\n';
	}
}

int main {
	ios::sync_with_stdio(0);
	cin.tie(0);
	int T;
	cin >> T;
	while (T--) {
		solve;
	}
	return 0;
}
