**Hint 1**

What is the value of $f(c)$?

**Hint 2**

Try DP.

**Hint 3**

Optimize the DP in G1.

**Solution**

First, we establish (as in G1) that $f(c)$ for a sequence $c$ of length $k$ equals the $\lceil k/2 \rceil$-th largest element, i.e., the "upper median". The total beauty of a permutation $p$ is $\sum_{1 \le i \le j \le n} f(p_i, \ldots, p_j)$.

The key insight for computing the beauty: assign to each value $v$ at position $\text{pos}(v)$ a sign $\sigma_v \in \{0, 1\}$ (0 = even parity, 1 = odd parity) based on the rank of $v$ among $\{1, \ldots, v\}$ sorted by their positions. The total beauty equals $\sum_v v^2 - \sum_v v \cdot c_v$ where $c_v = (n/2 - (\text{count of values} < v \text{ with parity 1}) \cdot [\sigma_v = 1]) + (\lceil n/2 \rceil - (\text{count of values} < v \text{ with parity 0}) \cdot [\sigma_v = 0])$... 

More precisely: the total cost (to be minimized, subtracted from $\sum i^2$) is $\sum_{i=1}^n [j_i \cdot (n/2 - (i - j_i)) + (i - j_i) \cdot (\lceil n/2 \rceil - j_i)]$ where $j_i$ = number of values in $\{1,\ldots,i\}$ at odd positions.

The DP state in G1 is $f[i][j]$ = minimum cost for placing values $1,\ldots,i$ with $j$ of them at odd positions, which is $O(n^2)$ states and $O(n^2)$ total time (feasible for $n \le 5000$).

For G2 ($n \le 5 \times 10^5$), we need to optimize this to $O(n \log n)$.

The cost at step $i$ for state $j$ is $j(n/2 - i + j) + (i-j)(\lceil n/2 \rceil - j) = j \cdot n/2 - ji + j^2 + (i-j)\lceil n/2 \rceil - j(i-j)$. This simplifies to a quadratic in $j$: $2j^2 + j(-i - i - (n \mod 2)) + i\lceil n/2 \rceil$.

So at each step $i$, the DP values get modified by adding $2j^2 - (2i + (n\&1))j + i\lceil n/2\rceil$ to $f[i][j]$. This is a quadratic function applied to all $j$ values simultaneously.

The key observation: the DP transitions are:
1. Add a quadratic function of $j$ to all states (matrix: $f[j] \to f[j] + 2j^2 - (2i+(n\&1))j + ...$)
2. Shift: either keep $j$ (for even parity assignment) or increment $j$ (for odd parity assignment), or both.

With a treap (balanced BST) maintaining the DP values indexed by $j$, we can:
- Apply the quadratic cost as a lazy tag using a 3D affine transformation on $(f, j, 1)$ (the vec stores $(f_j, j, 1)$ and the tag is a $3\times3$ matrix).
- Split at the boundary where $f_j < 0$ (which tracks the optimal $j$ value).
- Insert new nodes for free positions.

The matrix transformation for adding $2j^2 - (2i + (n\&1))j$ to $f_j$: since $j^2$ is fixed for each node, we track $(f_j, j, 1)$ as a vector and apply matrix:
$$\begin{pmatrix} 1 & 0 & 0 \\ 4 & 1 & 0 \\ -(2i+(n\&1))-2 & 0 & 1 \end{pmatrix}$$
which transforms $(f, j, 1) \to (f + 4j - (2i+(n\&1))-2, j, 1)$... Actually looking at the code more carefully:

The vec stores $(\Delta_j, j, 1)$ where $\Delta_j = f[j] - $ (base terms), and the matrix update corresponds to incrementally adding the cost differences as we process each value $i$.

The full implementation uses a treap with lazy matrix multiplication tags. Each node stores $(f_j - \text{offset}, j, 1)$ as a 3-vector, and we apply $3\times3$ matrix tags. When processing value $i$:
1. Apply the cost update matrix to the entire treap.
2. If value $i+1$ has a fixed parity, apply a shift to the relevant subtree.
3. If value $i+1$ is free, split the treap at $j = $ current count, add a new node for the new free position.

After processing all $n$ values, traverse the treap to extract $f[j]$ for all $j$, then find $f[(n+1)/2]$ and compute the answer.

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int maxn = 500100;

int n, a[maxn];
mt19937 rnd(chrono::steady_clock::now.time_since_epoch.count);

int p[maxn], nt, ls[maxn], rs[maxn], sz[maxn];
bool vis[maxn];

struct vec {
	ll a0, a1, a2;
	vec(ll a = 0, ll b = 0, ll c = 0) : a0(a), a1(b), a2(c) {}
} val[maxn];

struct mat {
	ll a00, a01, a02, a10, a11, a12, a20, a21, a22;
	mat(ll a = 0, ll b = 0, ll c = 0, ll d = 0, ll e = 0, ll f = 0, ll g = 0, ll h = 0, ll i = 0) : a00(a), a01(b), a02(c), a10(d), a11(e), a12(f), a20(g), a21(h), a22(i) {}
} I, tag[maxn];

inline vec operator * (const vec &a, const mat &b) {
	vec res;
	res.a0 = a.a0 * b.a00 + a.a1 * b.a10 + a.a2 * b.a20;
	res.a1 = a.a0 * b.a01 + a.a1 * b.a11 + a.a2 * b.a21;
	res.a2 = a.a0 * b.a02 + a.a1 * b.a12 + a.a2 * b.a22;
	return res;
}

inline mat operator * (const mat &a, const mat &b) {
	mat res;
	res.a00 = a.a00 * b.a00 + a.a01 * b.a10 + a.a02 * b.a20;
	res.a01 = a.a00 * b.a01 + a.a01 * b.a11 + a.a02 * b.a21;
	res.a02 = a.a00 * b.a02 + a.a01 * b.a12 + a.a02 * b.a22;
	res.a10 = a.a10 * b.a00 + a.a11 * b.a10 + a.a12 * b.a20;
	res.a11 = a.a10 * b.a01 + a.a11 * b.a11 + a.a12 * b.a21;
	res.a12 = a.a10 * b.a02 + a.a11 * b.a12 + a.a12 * b.a22;
	res.a20 = a.a20 * b.a00 + a.a21 * b.a10 + a.a22 * b.a20;
	res.a21 = a.a20 * b.a01 + a.a21 * b.a11 + a.a22 * b.a21;
	res.a22 = a.a20 * b.a02 + a.a21 * b.a12 + a.a22 * b.a22;
	return res;
}

inline void init {
	for (int i = 0; i <= nt; ++i) {
		p[i] = ls[i] = rs[i] = sz[i] = 0;
		val[i] = vec;
		tag[i] = I;
		vis[i] = 0;
	}
	nt = 0;
}

inline int newnode(ll x, ll y) {
	int u = ++nt;
	p[u] = rnd;
	ls[u] = rs[u] = 0;
	sz[u] = 1;
	val[u] = vec(x, y, 1);
	tag[u] = I;
	vis[u] = 0;
	return u;
}

inline void pushup(int x) {
	sz[x] = sz[ls[x]] + sz[rs[x]] + 1;
}

inline void pushtag(int x, const mat &y) {
	if (!x) {
		return;
	}
	val[x] = val[x] * y;
	tag[x] = tag[x] * y;
	vis[x] = 1;
}

inline void pushdown(int x) {
	if (!vis[x]) {
		return;
	}
	pushtag(ls[x], tag[x]);
	pushtag(rs[x], tag[x]);
	vis[x] = 0;
	tag[x] = I;
}

void split(int u, int &x, int &y) {
	if (!u) {
		x = y = 0;
		return;
	}
	pushdown(u);
	if (val[u].a0 < 0) {
		x = u;
		split(rs[u], rs[u], y);
	} else {
		y = u;
		split(ls[u], x, ls[u]);
	}
	pushup(u);
}

int merge(int x, int y) {
	if (!x || !y) {
		return x | y;
	}
	pushdown(x);
	pushdown(y);
	if (p[x] < p[y]) {
		rs[x] = merge(rs[x], y);
		pushup(x);
		return x;
	} else {
		ls[y] = merge(x, ls[y]);
		pushup(y);
		return y;
	}
}

ll f[maxn], tot;

void dfs(int u) {
	if (!u) {
		return;
	}
	pushdown(u);
	dfs(ls[u]);
	f[++tot] = val[u].a0;
	dfs(rs[u]);
}

void solve {
	cin >> n;
	for (int i = 1; i <= n; ++i) {
		a[i] = -1;
	}
	for (int i = 1, x; i <= n; ++i) {
		cin >> x;
		if (x) {
			a[x] = (i & 1);
		}
	}
	init;
	int rt = 0;
	ll l = 0, r = 0, x = 0;
	if (a[1] == 1) {
		l = r = 1;
	} else if (a[1] == -1) {
		rt = newnode(0, 1);
		r = 1;
	}
	for (ll i = 1; i < n; ++i) {
		x += l * l * 2 + (-i - i - (n & 1)) * l + i * ((n + 1) / 2);
		pushtag(rt, mat(1, 0, 0, 4, 1, 0, -i - i - (n & 1) - 2, 0, 1));
		if (a[i + 1] == 1) {
			pushtag(rt, mat(1, 0, 0, 0, 1, 0, 0, 1, 1));
			++l;
			++r;
		} else if (a[i + 1] == -1) {
			int u, v;
			split(rt, u, v);
			pushtag(v, mat(1, 0, 0, 0, 1, 0, 0, 1, 1));
			rt = merge(merge(u, newnode(0, l + 1 + sz[u])), v);
			++r;
		}
	}
	tot = 0;
	dfs(rt);
	ll ans = -x;
	for (int i = 1; i <= (n + 1) / 2 - l; ++i) {
		ans -= f[i];
	}
	for (ll i = 1; i <= n; ++i) {
		ans += i * i;
	}
	cout << ans << '\n';
}

int main {
	ios::sync_with_stdio(0);
	cin.tie(0);
	I.a00 = I.a11 = I.a22 = 1;
	int T;
	cin >> T;
	while (T--) {
		solve;
	}
	return 0;
}
```

**Hint 1**

Extract the longest contiguous segments in $s$ where the values remain the same.

**Hint 2**

According to greedy matching, an $O(n^2)$ DP can be obtained.

**Hint 3**

Optimize the DP from $O(n^2)$ to $O(n)$.

**Solution**

First, compress the binary string $s$ into runs: replace each maximal block of identical characters with its length. Let the runs be $a_1, a_2, \ldots, a_m$ (with alternating 0s and 1s). 

Special cases:
- If $m = 1$: all characters are the same, answer is $n - 1$.
- If $m = 2$: answer is $a_1 \cdot a_2$.

For $m \ge 3$: we need to count the number of distinct binary sequences obtainable.

The key observation about the operation: choosing index $i$ on a subarray $[s_i, s_{i+1}, s_{i+2}]$, the median is removed. For a binary sequence, the median of three elements $\{x, y, z\}$ is the majority value. So:
- If all three are the same (say all 0): median is 0, and the leftmost (smallest $j \ge i$ with $s_j = 0$) is removed, which is $s_i$.
- If two are 0 and one is 1 (or vice versa): the median is the majority.

Think in terms of runs. The operation essentially can reduce run lengths. The reachable sequences from the run-length representation $[a_1, a_2, \ldots, a_m]$ are characterized by choosing subsets of runs with certain constraints.

The reachable sequences are represented by choosing a subsequence of runs $[a_{i_1}, a_{i_2}, \ldots, a_{i_k}]$ (keeping runs in order, alternating 0s and 1s) where the chosen lengths satisfy certain inequalities. Specifically, the final sequence is determined by choosing how many elements to keep from each run, subject to greedy matching constraints.

More precisely, a reachable sequence is encoded by its run-length representation $[b_1, b_2, \ldots, b_l]$ (a subsequence of original run types) where each $b_j$ is between 1 and $a_{i_j}$ (the corresponding original run), and the "gaps" can be absorbed. The constraint is based on which runs can be merged/eliminated.

The DP counts the number of such valid $(b_1, \ldots, b_l)$ tuples. Let $f[i]$ = number of distinct sequences ending with (something from) the $i$-th run. The transition considers which original run the previous kept run came from.

To define it precisely: we count pairs $(i, v)$ where $i$ is the index of the last kept run and $v \in [1, a_i]$ is the length of that last run, such that the total length is some valid length. The function $\text{nxt}[i]$ gives the next run of the same parity that can be jumped to.

The DP $f[i]$ counts the number of ways to choose the last run as run $i$ with some valid length, accumulated over all valid preceding sequences. The transition from $i$ to $j$ (where $j > i$, same or next parity) multiplies by the number of valid last-run lengths.

The optimization to $O(n)$: compute $\text{nxt}[i]$ (the next run of same parity with strictly greater "adjusted height" $a_j - j/2$) using a monotone stack. Then the DP transitions can be batched: from run $i$ to its next "dominating" run $\text{nxt}[i]$, the contribution can be computed in $O(1)$ using prefix sums and difference arrays.

The final answer adds contributions from two cases: sequences ending with an even-indexed run and sequences ending with an odd-indexed run, multiplied by the last run's length $a_m$ (for the rightmost run constraint).

Implementation details: two passes of `calc` are performed — one on the original runs and one on a modified version (shifting by one to account for the two possible boundary conditions).

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int maxn = 2000100;
const ll mod = 1000000007;

int n, a[maxn], m, nxt[maxn], stk[maxn], top;
ll f[maxn], g[maxn], d[maxn];
char s[maxn];

inline ll calc {
	top = 0;
	for (int i = m; i >= 1; i -= 2) {
		while (top && a[stk[top]] - stk[top] / 2 < a[i] - i / 2) {
			--top;
		}
		nxt[i] = stk[top];
		stk[++top] = i;
	}
	top = 0;
	for (int i = m - 1; i >= 1; i -= 2) {
		while (top && a[stk[top]] - stk[top] / 2 < a[i] - i / 2) {
			--top;
		}
		nxt[i] = stk[top];
		stk[++top] = i;
	}
	for (int i = 1; i < m; ++i) {
		f[i] = g[i] = d[i] = 0;
	}
	f[1] = a[1];
	for (int i = 3; i < m; i += 2) {
		f[i] = 1;
	}
	ll ans = 0;
	for (int i = 1; i < m; ++i) {
		if (i >= 3) {
			d[i] = (d[i] + d[i - 2]) % mod;
		}
		f[i] = (f[i] + d[i]) % mod;
		g[i + 1] = (g[i + 1] + f[i]) % mod;
		f[i + 1] = (f[i + 1] + f[i] * a[i + 1]) % mod;
		d[i + 2] = (d[i + 2] + g[i]) % mod;
		if (nxt[i]) {
			g[nxt[i]] = (g[nxt[i]] + g[i]) % mod;
			f[nxt[i]] = (f[nxt[i]] + g[i] * (a[nxt[i]] - a[i] - (nxt[i] - i) / 2 + 1)) % mod;
			d[nxt[i]] = (d[nxt[i]] - g[i] + mod) % mod;
		}
		if ((m - i) & 1) {
			ans = (ans + f[i]) % mod;
		}
	}
	return ans * a[m] % mod;
}

void solve {
	cin >> n >> s;
	m = 0;
	for (int i = 0, j = 0; i < n; i = (++j)) {
		while (j + 1 < n && s[j + 1] == s[i]) {
			++j;
		}
		a[++m] = j - i + 1;
	}
	if (m == 1) {
		cout << n - 1 << '\n';
		return;
	}
	if (m == 2) {
		cout << 1LL * a[1] * a[2] % mod << '\n';
		return;
	}
	ll ans = calc;
	--m;
	for (int i = 1; i <= m; ++i) {
		a[i] = a[i + 1];
	}
	a[1] = 1;
	ans = (ans + calc) % mod;
	cout << ans << '\n';
}

int main {
	ios::sync_with_stdio(0);
	cin.tie(0);
	int T;
	cin >> T;
	while (T--) {
		solve;
	}
	return 0;
}
```

**Hint 1**

Do not go for DP.

**Hint 2**

How many plates of sushi can be taken?

**Hint 3**

What are the constraints on the time of taking plates of sushi?

**Solution**

Note that the last $i$-th time taking a plate of sushi should be no later than the $(n - i\cdot(k+1) + 1)$-th minute. This constraint limits the time that a taking action can be performed. Therefore, we enumerate the $n$ minutes in chronological order, and greedily take the untaken plates delivered before with the greatest deliciousness when we reach a constraint, i.e., the current minute is the $(n - i\cdot(k+1) + 1)$-th minute for a certain $i$. The deliciousnesses of the untaken plates can be maintained by a heap. The total complexity is $O(n \log n)$.

**Code (C++)**

```
#include <cstdio>
#include <queue>

using namespace std;

const int N = 2e5 + 5;

int n, k;
int d[N];
long long ans;

void solve {
	scanf("%d%d", &n, &k);
	ans = 0;
	priority_queue <int> q;
	for (int i = 1; i <= n; i++) {
		scanf("%d", &d[i]);
		q.push(d[i]);
		if ((n - i + 1) % (k + 1) == 0) {
			ans += q.top;
			q.pop;
		}
	}
	printf("%lld\n", ans);
}

int main {
	int t;
	scanf("%d", &t);
	while (t--)
		solve;
	return 0;
}
