				else {
					(e[0] += pb) %= MOD;
					(p[nxt][j][0] += pb) %= MOD;
				}
			}
		}

		now ^= 1;
		nxt ^= 1;
		memset(p[nxt], 0, sizeof(int) * MAXK * MAXN);
	}
	for (i = 1; i < n; ++i) (e[i] += e[i - 1]) %= MOD;

