        int pr = l;
        int ans = 0;
        for (auto [idx, val]: facts) {
            int rr = idx - pr;
            ans += v * rr;
            while (v % val == 0) v /= val;
            pr = idx;
        }
        if (facts.empty) ans = v * (r - l + 1);
        else ans += (r - pr + 1) * v;
        anss[idd] = ans;
    }
    for (int i = 0; i < q; i++) cout << anss[i] << "\n";
}

signed main {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    int t; cin >> t;
    while (t--) solve;
    return 0;
}
