    long long y = 0;
    for (int i = 0; i < n; i++) {
        a[i] = max(l[i], r[i]);
        b[i] = min(l[i], r[i]);
        y += a[i];
    }

    sort(b.begin, b.end, greater<>);
    for (int i = 0; i < m; i++) {
        y += b[i];
    }

    long long x = y + 1;
    cout << x << '\n';
}

int main {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    for (int i = 0; i < t; i++) {
        test;
    }

    return 0;
}
