                ri[i] = min(ri[i] , br[i+1]-1);
            }

            if(a[i] < a[i+1] && a[sr[i+1]] > a[i]){
                ri[i] = min(ri[i] , sr[i+1]-1);
            }
        }

        le[1] = 1 ;
        rep(i , 2,n){
            le[i] = le[i-1] ;
            if(a[i] > a[i-1] && a[bl[i-1]] < a[i]){
                le[i] = max(le[i] , bl[i-1]+1);
