        le[1] = 1 ;
        rep(i , 2,n){
            le[i] = le[i-1] ;
            if(a[i] > a[i-1] && a[bl[i-1]] < a[i]){
                le[i] = max(le[i] , bl[i-1]+1);
            }
            if(a[i] < a[i-1] && a[sl[i-1]] > a[i]){
                le[i] = max(le[i] , sl[i-1]+1);
            }
        }

        int ans = ri[1] ;
        rep(i , 2 , n){
            ans = (ans + (i-1 - le[i] + 1) * (ri[i] - ri[i-1]) + ri[i]-i+1) ;
        }
