                    used[k] = true;
                    k = p[k];
                }
            }
        }

        sort(ans.begin, ans.end, greater<array<int, 3>>);
        for (auto [x, y, z] : ans){
            cout << x << " " << y << " " << z << " ";
        }
        cout << '\n';
    }
    return 0;
}
