#include <cstdio>
#include <algorithm>
#include <cstring>

#define S 100005

typedef long long l;

l a[S], d[S], n;

bool check(l ans) {
    memset(d, 0, sizeof(l) * n);
    l acc = 0;

    for (l i = 0; i < n; ++i) {
        acc -= d[i];

        l need = std::max(0LL, i - (n - ans));
        if (acc < need) return false;

        l end = i + a[i] + (acc++) - need + 1;
        if (end < n) ++d[end];
    }

    return true;
}

void solve {
    scanf("%lld", &n);
    for (l i = 0; i < n; ++i) scanf("%lld", &a[i]);

    l le = 1, ri = n + 1, mid;
    while (ri - le > 1) {
        mid = (le + ri) / 2;
        if (check(mid)) le = mid;
        else ri = mid;
    }

    printf("%lld\n", le);
}

int main {
    l tc; scanf("%lld", &tc);
    while (tc--) solve;
}
