        return _fac[m];
    }

    mint ifac(int m){
        check_size(m);
        return _ifac[m];
    }

    mint ncr(int n, int r){
        if (n < r || r < 0) return 0;

        return fac(n) * ifac(n - r) * ifac(r);
    }

    mint npr(int n, int r){
        if (n < r || r < 0) return 0;

        return fac(n) * ifac(n - r);
    }
