        }
    }

    min_max(int a, int b){
        mx1 = mn1 = a;
        mx2 = mn2 = b;
        fix_mx;
        fix_mn;
    }

    void add(int x){
        mx2 = max(mx2, x);
        mn2 = min(mn2, x);
        fix_mx;
        fix_mn;
    }

    int get_seg(int x){
        pair<int, int> res = {mn1, mx1};
        if(x == mn1) res.x = mn2;
        if(x == mx1) res.y = mx2;
        return res.y - res.x + 1;
    }
};

void solve(int tc){
    int n;
    cin >> n;
    vector<pair<int, int>> coord(n);
    for(auto &e: coord){
        cin >> e.x >> e.y;
    }
    if(n <= 2){
        cout << n;
        return;
    }

    min_max xc(coord[0].x, coord[1].x), yc(coord[0].y, coord[1].y);
    for(int i = 2; i < n; ++i){
        xc.add(coord[i].x);
        yc.add(coord[i].y);
    }

    int ans = xc.get_seg(-1) * yc.get_seg(-1);
    for(int i = 0; i < n; ++i){
        int x = xc.get_seg(coord[i].x);
        int y = yc.get_seg(coord[i].y);
        if(x * y == n - 1){
            ans = min(ans, min((x + 1) * y, x * (y + 1)));
        }
        else{
            ans = min(ans, x * y);
        }
    }
    cout << ans;
}

bool multi = true;

