We want to transform $x$ into $y$ using minimum operations (multiply or divide by $a \le k$). First, divide both $x$ and $y$ by $\gcd(x, y)$, getting $x'$ and $y'$. Now we need to transform $x' \cdot g$ into $y' \cdot g$, which means we need to divide $x'$ to 1 and multiply 1 to $y'$ (since they share no common factors after dividing by gcd).

So the answer is: minimum operations to reduce $x'$ to 1, plus minimum operations to build $y'$ from 1. Each of these is a shortest path problem on divisors.

For a number $x'$, find all its divisors. Sort them. Use DP where $dp[d]$ = minimum steps to reach divisor $d$ from 1 (by multiplying by values $\le k$). The answer for reducing $x'$ to 1 is the same as building $x'$ from 1 (operations are reversible). If either reduction is impossible (answer = -1), output -1.

**Solution**

```
#include <bits/stdc++.h>

#define int long long
#define pb emplace_back
#define mp make_pair
#define x first
#define y second
#define all(a) a.begin, a.end
#define rall(a) a.rbegin, a.rend

typedef long double ld;
typedef long long ll;

using namespace std;

mt19937 rnd(time(nullptr));

const int inf = 1e9;
const int M = 1e9 + 7;
const ld pi = atan2(0, -1);
const ld eps = 1e-6;

int gcd(int a, int b) {
    return b == 0 ? a : gcd(b, a % b);
}

int get_ans(int x, int k){
    if(x == 1) return 0;
    vector<int> divs;
    for(int i = 1; i * i <= x; i++){
        if(x % i == 0){
            divs.push_back(i);
            divs.push_back(x / i);
        }
    }
    sort(all(divs));
    int n = divs.size;
    vector<int> dp(n, 100);
    dp[0] = 0;
    for(int i = 1; i < n; i++){
        for(int j = i - 1; j >= 0; j--){
            if(divs[i] / divs[j] > k){
                break;
            }
            if(divs[i] % divs[j] == 0) {
                dp[i] = min(dp[i], dp[j] + 1);
            }
        }
    }
    return dp[n - 1] == 100 ? -1 : dp[n - 1];
}

void solve(int tc){
    int x, y, k;
    cin >> x >> y >> k;
    int g = gcd(x, y);
    x /= g;
    y /= g;
    int ax = get_ans(x, k);
    int ay = get_ans(y, k);
    if(ax == -1 || ay == -1) cout << -1;
    else cout << ax + ay;
}

bool multi = true;

signed main {
    int t = 1;
    if (multi) cin >> t;
    for (int i = 1; i <= t; ++i) {
        solve(i);
        cout << "\n";
    }
    return 0;
}
```

Each element $a_i$ in the final array was built from some initial insertions. The key function is `max_op(a, b)`: given a final element value $a$ and the value of its neighbor $b$ (or 0 if it's an endpoint), compute the maximum number of operations that could have been used to build $a$ given that its neighbor on that side is $b$.

When building element $a$ adjacent to neighbor $b$: we can recursively split $a$ into two equal halves (each half is inserted separately), as long as the half equals $b$ we must stop. The maximum operations for building $a$ given neighbor $b$: repeatedly halve $a$ until we reach $b$ or reach an odd number. Count the steps.

For each element $a_i$, the total maximum operations when $a_i$ is the "center" (last element placed) is:
- `max_op(a[i], 0)` for the element itself (no neighbor constraint)
- plus sum of `max_op(a[j-1], a[j])` for all left neighbors (pre[i])
- plus sum of `max_op(a[j+1], a[j])` for all right neighbors (suf[i])

If this total $\ge k$ for any choice of center element $i$, output YES (since we can always use fewer operations by using multiplier 1).

**Solution**

```
#include <bits/stdc++.h>

#define int long long
#define pb emplace_back
#define mp make_pair
#define x first
#define y second
#define all(a) a.begin, a.end
#define rall(a) a.rbegin, a.rend

typedef long double ld;
typedef long long ll;

using namespace std;

mt19937 rnd(time(nullptr));

const int inf = 1e9;
const int M = 1e9 + 7;
const ld pi = atan2(0, -1);
const ld eps = 1e-6;

int max_op(int a, int b) {
    int min_part = a;
    while (min_part % 2 == 0 && min_part / 2 != b) {
        min_part /= 2;
    }
    if (min_part % 2 == 1) {
        return a / min_part;
    }
    int true_min = min_part;
    while (true_min % 2 == 0) {
        true_min /= 2;
    }
    return 1 + (a - min_part) / true_min;
}

void solve(int tc){
    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int &e: a) cin >> e;
    vector<int> pre(n, 0);
    for (int j = 1; j < n; ++j) {
        pre[j] = pre[j - 1] + max_op(a[j - 1], a[j]);
    }
    vector<int> suf(n, 0);
    for (int j = n - 2; j >= 0; --j) {
        suf[j] = suf[j + 1] + max_op(a[j + 1], a[j]);
    }
    for (int i = 0; i < n; i++) {
        int res = max_op(a[i], 0) + pre[i] + suf[i];
        if (res >= k) {
            cout << "YES";
            return;
        }
    }
    cout << "NO";
}

bool multi = true;

signed main {

    int t = 1;
    if (multi) cin >> t;
    for (int i = 1; i <= t; ++i) {
        solve(i);
        cout << "\n";
    }
    return 0;
}
```

Let $g = \gcd(a_1, a_2, \dots, a_n)$, It can be shown that eventually all elements become $g$.

Consider the assumption that eventually all numbers are $x$. Then for all $i$, there is $x\ |\ a_i$; this is because as $a_i := \gcd(a_i, a_j)$, the new $a_i$ value will only be a factor of the original. It further follows that $x\ |\ g$.

Further analysis reveals that $x$ cannot be less than $g$, no matter how it is manipulated. Thus we have $x = g$.

Next we consider that after a certain number of operations, if there exists some $a_k$ equal to $g$. In the next operations, for each element $a_i$ that is not equal to $g$, we simply choose $j=k$ and then make $a_i := \gcd(a_i, a_k)$. After this, all elements will become $g$.

If $g$ is initially in $a$, then the problem is simple; we just need to count the number of elements in $a$ that are not equal to $g$.

But if the initial $g$ is not in $a$, we are actually trying to make an element equal to $g$ by minimizing the number of operations.

This is not difficult to achieve through dynamic programming, using $f_x$ to indicate that it takes at least a few operations to make an element equal to $x$.

The transition is simple, just enumerate $x$ from largest to smallest, and then for all $i$, use $f_{x}+1$ to update $f_{\gcd(x, a_i)}$.

But computing $\gcd(x, y)$ is $O(\log x)$, a direct transition takes $O(n \max(a) \log \max(a))$ time. So we need to preprocess this. Let $h_{x, y} = \gcd(x, y)$, then there is obviously $h_{x, y} = h_{y, x \bmod y}$. Before all test cases, $h$ can be preprocessed in $O(\max(a)^2)$ time complexity.

Time complexity: $O(n \max(a))$ per test case and $O(\max(a)^2)$ for preprocessing.

Memory complexity: $O(n+\max(a))$ per test case and $O(\max(a)^2)$ for preprocessing.

**Bonus**

Try to solve $n, a_i \leq 2 \times 10^5$ with only one test case.

**Code**

```
#include<bits/stdc++.h>

using namespace std;

const int N = 5000 + 5;

inline void checkmax(int &x, int y){
	if(y > x) x = y;
}

inline void checkmin(int &x, int y){
	if(y < x) x = y;
}

int n = 0, m = 0, k = 0, a[N] = {}, f[N] = {};
int g[N][N] = {}, ans = 0;

inline void solve{
	scanf("%d", &n); m = k = 0;
	for(int i = 1 ; i <= n ; i ++){
		scanf("%d", &a[i]);
		k = g[k][a[i]];
	}
	memset(f, 0x3f, sizeof(f));
	for(int i = 1 ; i <= n ; i ++) a[i] /= k, checkmax(m, a[i]), f[a[i]] = 0;
	for(int x = m ; x >= 1 ; x --) for(int i = 1 ; i <= n ; i ++){
		int y = a[i];
		checkmin(f[g[x][y]], f[x] + 1);
	}
	ans = max(f[1] - 1, 0);
	for(int i = 1 ; i <= n ; i ++) if(a[i] > 1) ans ++;
