Root the tree at vertex 1. Maintain the current total cost. For each vertex $v$, store $cnt[v]$: a map from color to the sum of edge weights of children edges where the child has that color. Also store $zn[v]$: the weight of the edge connecting $v$ to its parent.

When we update vertex $v$ from color $col[v]$ to color $x$:
- Update the parent's contribution: subtract the edge weight from the parent's count for the old color, add it for the new color, and adjust $costt$ accordingly (if parent's color matched old color, cost increases; if it matches new color, cost decreases).
- Update $costt$ based on children: add back $cnt[v][col[v]]$ (edges to children that were free now become costly) and subtract $cnt[v][x]$ (edges to children that were costly now become free).

```cpp
#include <bits/stdc++.h>
using namespace std;
const int B = 2e5 + 100;
int n;
int col[B];
long long costt = 0;
vector <pair <int,int> > reb[B];
bool was[B];
map <int,long long> cnt[B];
int pred[B];
long long zn[B];
void dfs(int v) {
  was[v] = true;
  for(auto u:reb[v]) {
    if(was[u.first]) {
      pred[v] = u.first;
      continue;
    }
    if(col[v] != col[u.first]) costt+=u.second;
    dfs(u.first);
    zn[u.first] = u.second;
    cnt[v][col[u.first]]+=zn[u.first];
  }
}
void update(int v,int x) {
  if(v != 1) {
    cnt[pred[v]][col[v]]-=zn[v];
    if(col[pred[v]] == col[v]) costt+=zn[v];
    cnt[pred[v]][x]+=zn[v];
    if(col[pred[v]] == x) costt-=zn[v];
  }
  costt+=cnt[v][col[v]];
  costt-=cnt[v][x];
  col[v] = x;
}
void clr {
  for(int i = 1;i <= n;i++) {
    reb[i].clear;
    was[i] = false;
    cnt[i].clear;
    zn[i] = 0;
  }
  costt = 0;
}
int main {
  int t;
  cin >> t;
  while(t--) {
    int q;
    cin >> n >> q;
    for(int i = 1; i <= n; i++) cin >> col[i];
    for(int i = 1; i < n; i++) {
      int u, v, c;
      cin >> u >> v >> c;
      reb[v].push_back({u,c});
      reb[u].push_back({v,c});
    }
    dfs(1);
    while(q--) {
      int pos,x;
      cin >> pos >> x;
      update(pos,x);
      cout << costt << "\n";
    }
    clr;
  }
}
