    int ans = 0;
    for(int i = 1;i <= 100;i++) {
      int b[n + 1] = {};
      for(int j = 1;j <= n;j++) {
        if(a[j] >= i) b[j] = 1;
        else b[j] = -1;
      }
      int pref[n + 1] = {};
      for(int j = 1; j <= n; j++) {
        pref[j] = pref[j - 1] + b[j];
      }
      int prefmn[n + 2] = {},suffmx[n + 1] = {};
      prefmn[0] = 0,suffmx[n] = pref[n];
      for(int j = 1; j <= n; j++) {
        prefmn[j] = min(prefmn[j - 1],pref[j]);
      }
      for(int j = n - 1; j >= 1; j--) {
        suffmx[j] = max(suffmx[j + 1],pref[j]);
      }
      for(int j = 1; j <= n; j++) {
        if(prefmn[j - 1] <= pref[j] || pref[j - 1] <= suffmx[j]) {
          ans = max(ans,i - a[j]);
        }
      }
    }
    cout << ans << endl;
  }
}
