  cin.tie(0);
  int t;
  cin >> t;
  while (t--) {
    int n;
    cin >> n;

    vector<int> a(n);
    auto swap = [&](int x) {
      cout << "swap " << x + 1 << endl;
    };
    auto throw_ball = [&](int x) {
      cout << "throw " << x + 1 << endl;
      int ret;
      cin >> ret;
      return ret;
    };
    auto answer = [&] {
      cout << "!";
      for (auto i : a)
        cout << ' ' << i;
      cout << endl;
    };

    vector<int> jumps(n + 2);
    for (int i = n - 1; i >= 0; i--) {
      if (jumps[i + 1] == jumps[i + 2]) {
        jumps[i] = jumps[i + 1] + 1;
      } else {
        jumps[i] = throw_ball(i);
        if (jumps[i] == jumps[i + 1] + 1)
          a[i] = 1;
        else
          a[i] = 2;
      }
    }
    for (int i = 0; i + 1 < n; i++) {
      if (a[i] == 0) {
        swap(i);
        int jumps_i = throw_ball(i + 1);
        if (jumps_i == jumps[i + 2] + 1)
          a[i] = 1;
        else
          a[i] = 2;
      }
    }
    swap(n - 2);
    int jumps_last = throw_ball(n - 2);
    if (jumps_last == 2)
      a[n - 1] = 1;
    else
      a[n - 1] = 2;
    answer;
  }
}
