      if (j == 0 || j == i)
        binom_[i][j] = 1;
      else
        binom_[i][j] = binom_[i - 1][j] + binom_[i - 1][j - 1];
    }
  auto binom = [&](int x, int y) {
    if (x >= y && y >= 0 && x >= 0)
      return binom_[x][y];
    else
      return Mod(0);
  };

