int main {
	for (scanf("%d", &T); T--; ) {
		scanf("%d", &n);
		for (int i = 1; i <= n; i++) q[i].clear;
		for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
		for (int i = 1; i <= n; i++) {
			dp[i] = dp[i - 1], q[a[i]].emplace_back(i);
			if (q[a[i]].size > a[i]) q[a[i]].pop_front;
			if (q[a[i]].size == a[i]) dp[i] = max(dp[i], dp[q[a[i]].front - 1] + a[i]);
		}
		printf("%d\n", dp[n]);
	}
}
