const int N=81;
int a[N][N];
vector<pair<int,int>> e;
void add(int x,int y){
    e.push_back({x,y});
}
void make_matrix(int n){
    for(int i=2;i<n;++i) a[i][i]=1;
    a[n][1]=1;
    for(auto [x,y]:e) a[x][y]=-1;
}
int main{
    int _; scanf("%d",&_); //cin>>_;
    int max_bit=15;
    while(_--){
        memset(a,0,sizeof(a)); e.clear;
