def g(x, j):
    return x >> j & 1

def solve:
    L, R = map(int, input.split)
    a = [0] * (R - L + 1)

    def solve(l, r, j):
        if l > r:
            return
        if l == r:
            a[l - L] = r
            return
        mid = l
        while mid + 1 <= r and g(mid + 1, j) == g(l, j):
            mid += 1
        if mid == r:
            solve(l, r, j - 1)
            return
        tl = mid + 1
        tr = mid
        while tl - 1 >= l and tr + 1 <= r:
            tl -= 1
            tr += 1
            a[tl - L] = tr
            a[tr - L] = tl
        solve(l, tl - 1, j - 1)
        solve(tr + 1, r, j - 1)
        return

    solve(L, R, 29)
    ans = 0
    for i in range(L, R + 1):
        ans += a[i - L] | i
    print(ans)
    print(*a)
    return

t = int(input)
