        for (int j = 0; j < n; j++){
            if (a[j] == -1){
                spaces++;
                continue;
            }

            if (a[j] <= i){
                int need = a[j] - less - 1;
                res *= comb.ncr(spaces, need);
                more += spaces - need;
                less = a[j];

