void solve{
    int n;
    cin >> n;

    vector<int> a(n);
    for (int &x : a) {
        cin >> x;
        if (x != -1)
            x--;
    }

    bool fixed = true;
    for (int i = 0; i < n; i++)
        if (a[i] != -1 && a[i] != i)
            fixed = false;

    if (fixed){ //case where all a[i] != -1 has a[i] = i
        vector<mint> prod(n + 1);
        prod[0] = 1;
        for (int i = 1; i <= n; i++)
            prod[i] = prod[i - 1] * 2;

        int last = -1;
        mint ans = 0;
        for (int i = 0; i <= n; i++){
            if (i == n || a[i] != -1){
                int len = i - last - 1;
                ans += prod[len] - len - 1;
                last = i;
            }
        }

        ans += 1;
        cout << ans << "\n";
        return;
    }

    vector<bool> side(n);
    bool found = false;
    for (int i = 0; i < n; i++){
        if (a[i] == -1)
            continue;

        if (a[i] < i)
            side[i] = false; // left side
        if (a[i] > i)
            side[i] = true; // right side
        if (a[i] == i)
            side[i] = found;
        if (a[i] != i)
            found = true;
    }

    int last = -1;
    vector<array<int, 2>> ranges;
