        }
    }

    for(int i = 0;i < n;i++){
        for(int j = 0;j < m;j++){
            make_set(m*i+j,a[i][j]);
            for(auto &[p,q] : neighbours(i,j)){
                if(a[p][q] < a[i][j])important[m*i+j] = 0;
            }
        }
    }

    for(int i = 0;i < n;i++){
        for(int j = 0;j < m;j++){
            for(auto &[p,q] : neighbours(i,j)){
                if(a[p][q] == a[i][j])union_sets(m*i+j,m*p+q);
            }
        }
    }

    int ans = 0;
    for(int i = 0;i < n;i++){
        for(int j = 0;j < m;j++){
            if(parent[m*i+j] == m*i+j)ans+=important[m*i+j];
        }
    }

    cout << ans << "\n";

    int q;
    cin >> q;
    int nd = n*m;

    for(int i = 0;i < q;i++){
        int r,c,x;
        cin >> r >> c >> x;
        r--;c--;
        x = a[r][c] - x;
        set<int> s;

        int mn = INT_MAX;
        for(auto &[p,q] : neighbours(r,c)){
            s.insert(find_set(ls[p][q]));
            mn = min(mn,a[p][q]);
        }
        s.insert(find_set(ls[r][c]));

        for(auto &y : s){
            ans -= important[y];
        }

        for(auto &y : s){
            if(val[y] > x)important[y] = 0;
        }

        make_set(nd,x);
        if(mn < x)important[nd] = 0;
        else important[nd] = 1;

        for(auto &y : s){
            if(val[y] == x){
                union_sets(y,nd);
            }
        }

        a[r][c] = x;
        ls[r][c] = nd++;

        s.clear;
        for(auto &[p,q] : neighbours(r,c)){
            s.insert(find_set(ls[p][q]));
        }
        s.insert(find_set(ls[r][c]));

        for(auto &y : s){
            ans += important[y];
        }

        cout << ans << "\n";
    }

}

signed main{
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int t;
    cin >> t;
    while(t--)
        solve;
    return 0;
}
