The solution constructs numbers using products of prime powers. Each node in a $k\times k$ grid is assigned a number of the form $2^{i+j} \cdot 3^i \cdot 5^j \cdot 7^{k-1-i} \cdot 11^{k-1-j}$ for $0 \le i,j < k$.

The GCD of two such numbers (for nodes $(i_1,j_1)$ and $(i_2,j_2)$) is determined by the minimum exponents: it equals $2^{\min(i_1+j_1,i_2+j_2)} \cdot 3^{\min(i_1,i_2)} \cdot 5^{\min(j_1,j_2)} \cdot 7^{\min(k-1-i_1,k-1-i_2)} \cdot 11^{\min(k-1-j_1,k-1-j_2)}$, which is unique for each pair of adjacent nodes in an Eulerian path on the complete graph $K_k$.

The approach is to find an Eulerian path on $K_k$ (a complete graph on $k$ nodes), where visiting edge $(i,j)$ corresponds to outputting two consecutive elements with indices $i$ and $j$ in the grid. The minimum number of distinct elements needed is determined by finding the smallest $k$ such that the Eulerian path length $\ge n$.

The Eulerian path length for $K_k$ is $1 + \frac{k^2+k}{2} - (0 \text{ if } k \text{ is odd, else } \frac{k}{2}-1)$.

Eulerian paths on $K_k$ are built incrementally: the path for $K_k$ extends the path for $K_{k-2}$ by adding edges involving the two new nodes $x=k-2$ and $y=k-1$.

**Solution (Python)**
```python
from copy import deepcopy

def get_nums(k: int=10):
    nums = [
        2**(i + j) * 3**i * 5**j * 7**(k-1-i) * 11**(k-1-j)
        for i in range(k) for j in range(k)
    ]

    return nums

def eulerian_paths(max_k: int = 100):
    paths = [, [0, 0], [1,1,0,0]]

    for k in range(3, max_k + 1):
        path = deepcopy(paths[k - 2])
        x, y = k-2, k-1

        if k % 2:
            path.extend([x, x, y, y])
            for j in range(1, x, 2):
                path.extend([j, x, j+1, y])
            path.append(0)
        else:
            path.extend([x, x, 1, y, y])
            for j in range(2, x, 2):
                path.extend([j, x, j+1, y])
            path.append(0)

        paths.append(path)

    return paths

def path_len(k: int):
    return 1 + (k*k+k)//2 - (0 if k%2 else k//2-1)

if __name__ == "__main__":
    nums = get_nums(10)
    paths = eulerian_paths(100)

    for i in range(1, 101):
        assert len(paths[i]) == path_len(i)

    t = int(input)

    for _ in range(t):
        n = int(input)

        l, r = 0, 100
        while l < r-1:
            m = r - (r-l)//2
            if path_len(m) < n:
                l = m
            else:
                r = m

        path = paths[r]
        assert len(path) >= n

        a = [nums[i] for i in path[: n]]
        print(*a)
```

**Solution (C++)**
```cpp
#include "bits/stdc++.h"
using namespace std;

constexpr int64_t poww (int64_t a, int64_t p) {
    assert(p >= 0);
    int64_t res = 1;
    while (p > 0) {
        if (p & 1) res *= a;
        a *= a, p >>= 1;
    }
    return res;
}

constexpr int32_t path_len(const int32_t n) {
	return 1 + (n*n + n) / 2 - (n % 2 ? 0: n/2 - 1);
}

vector nums(0, 0ll);
vector walks(0, vector(0, 0));

void load_nums(const size_t p=10) {
	nums.resize(p * p);

	for (int i = 0; i < p; ++i)
		for (int j = 0; j < p; ++j)
			nums[i * 10 + j] = poww(2,(i+j)) * poww(3,i) * poww(5,j) * poww(7,(9-i)) * poww(11,(9-j));
}

void load_walks(const size_t max_k=100) {
	walks.resize(max_k + 1);
	walks[1] = vector({0, 0});
	walks[2] = vector({1, 1, 0, 0});

	for (int k = 3; k <= max_k; k++) {
		auto& walk = walks[k];
		walk = walks[k - 2];
		const int x = k-2, y = k-1;

		if (k % 2) {
			walk.push_back(x);
			walk.push_back(x);
			walk.push_back(y);
			walk.push_back(y);
			for (int j = 1; j < x; j += 2)
				walk.push_back(j),
				walk.push_back(x),
				walk.push_back(j+1),
				walk.push_back(y);
			walk.push_back(0);
		} else {
			walk.push_back(x);
			walk.push_back(x);
			walk.push_back(1);
			walk.push_back(y);
			walk.push_back(y);
			for (int j = 2; j < x; j += 2)
				walk.push_back(j),
				walk.push_back(x),
				walk.push_back(j+1),
				walk.push_back(y);
			walk.push_back(0);
		}
	}
}

void solve (const int kase) {

    int n; cin >> n;

    int l = 0, r = 100;
    while (l < r - 1) {
    	int m = r - (r-l) / 2;
    	if (path_len(m) < n)
    		l = m;
    	else
    		r = m;
    }

    vector a(n, 0ll);
    for (size_t i = 0; i < n; ++i) {
    	a[i] = nums[walks[r][i]];
    	cout << a[i] << ' ' ;
    }

    vector gcds(n-1, 0ll);
    for (size_t i = 1; i < n; ++i) {
    	gcds[i-1] = gcd(a[i], a[i - 1]);
    }

    assert(set(gcds.begin, gcds.end).size == n-1);

    cout << '\n';
}

int main  {
    ios_base::sync_with_stdio(0), cin.tie(0);

    load_nums;
    load_walks;

    for (size_t i = 1 ; i < 101; ++i)
    	assert(walks[i].size == path_len(i));

    int t; cin >> t, assert(t >= 0);
    for (int i = 0; t--; )
        solve(++i);

}
