#include <bits/stdc++.h>
#define N 500011
#define ll long long
using namespace std;
int T,n,q,a[N];
int main
{
	scanf("%d",&T);while(T--)
	{
		scanf("%d%d",&n,&q);
		for(int i=1;i<=n;++i)scanf("%d",a+i);
		sort(a+1,a+1+n,greater<int>);
		int nn=min(n,32);
		while(q--)
		{
			int c;scanf("%d",&c);
			static int b[44];ll ans=0;
			for(int i=1;i<=nn;++i)b[i]=a[i];
			for(int i=29;~i;--i)
			{
				int cc=0;
				for(int j=1;j<=nn;++j)cc+=b[j]>>i&1;
				if(cc>(c>>i&1))break;
				if(cc<(c>>i&1))
				{
					int id=1;
					for(int j=2;j<=nn;++j)if(b[j]>b[id])id=j;
					ans+=(1<<i)-b[id];
					b[id]=0;
				}
				else for(int j=1;j<=nn;++j)b[j]&=~(1<<i);
			}
			printf("%lld\n",ans);
