vector<int> pos[N * 2], dp[N * 2], tmp;
int solve
{
	int i, j, u, v, p;
	dp[1].resize(pos[1].size);
	for(i = 0; i < pos[1].size; i++)
		dp[1][i] = i;
	for(i = 1; i < m; i += 2)
	{
		u = pos[i].size - 1;
		v = pos[i + 2].size - 1;
		tmp.clear;
		tmp.resize(u + 1);
		dp[i + 2].clear;
		dp[i + 2].resize(v + 1);
		for(j = 0; j <= u; j++)
			tmp[j] = dp[i][j] - rp[pos[i][j]];
		for(j = u; j > 0; j--)
			tmp[j - 1] = max(tmp[j - 1], tmp[j]);
		for(j = 0; j <= v; j++)
		{
			p = pos[i + 2][j];
			if(j)
				dp[i + 2][j] = dp[i + 2][j - 1];
			if(Lp[p] < u)
				dp[i + 2][j] = max(dp[i + 2][j], j + tmp[Lp[p] + 1]);
			dp[i + 2][j] = max(dp[i + 2][j], j - lp[p] + dp[i][Lp[p]]);
		}
	}
	return dp[m].back;
}

