			vis[i] = 0;
		for(i = 1; i <= 2 * n; i++)
			pos[i].clear;
		for(i = 1; i <= n; i++)
			pos[a[i]].emplace_back(i);
		ans = n - solve;
		reverse(a + 1, a + n + 1);
		for(i = 1; i <= n; i++)
			vis[i] = 0;
		for(i = 1; i <= 2 * n; i++)
			pos[i].clear;
		for(i = 1; i <= n; i++)
			pos[a[i]].emplace_back(i);
		ans -= solve;
		printf("%d\n", ans);
	}
	return 0;
}
