			tmp[j] = dp[i][j] - rp[pos[i][j]];
		for(j = u; j > 0; j--)
			tmp[j - 1] = max(tmp[j - 1], tmp[j]);
		for(j = 0; j <= v; j++)
		{
			p = pos[i + 2][j];
			if(j)
				dp[i + 2][j] = dp[i + 2][j - 1];
			if(Lp[p] < u)
				dp[i + 2][j] = max(dp[i + 2][j], j + tmp[Lp[p] + 1]);
			dp[i + 2][j] = max(dp[i + 2][j], j - lp[p] + dp[i][Lp[p]]);
		}
	}
	return dp[m].back;
}

int main
{
	int t, n, i, ans;
	scanf("%d", &t);
	while(t--)
	{
