    int n;
    bool f[DB+1][1<<DB+1];
    int g[DB+1][1<<DB+1];
    void dp
    {
        n=DB;
        f[n][0]=1;
        for(int S=1;S<(1<<n);S<<=1)f[n][S]=1;
        for(int len=n;len>=2;len-=2)
        {
            for(int S=0;S<(1<<n);S++)
            {
                if(!f[len][S])continue;
                f[len-2][S]=1;
                g[len-2][S]=-1;
                for(int i=0;i+len-1<n;i++)
                {
                    f[len-2][S^(1<<i)^(1<<(i+len-1))]=1;
                    g[len-2][S^(1<<i)^(1<<(i+len-1))]=i;
                }
            }
        }
    }
    vector<int>ask(int S)
    {
        int len=0;
