        op(n-(n>>1),n);
        --n;
    }
    mid=(n+1>>1);
    if(!(mid&1))--mid;
    int p=solvec((mid>>1),(mid>>1)+2,(a[(mid>>1)+1]?(mid>>1)+1:0));
    solvep(mid+1,n,0,0);
    for(int i=1;i<=rn;++i)cout<<ans[i]<<' ';
    cout<<'\n';
}
int main
{
    DP::dp;
    int T;
    cin>>T;
    while(T--)solve;
    return 0;
}
