		}
		for(i=0;i<n;i++)
		{
			cin>>b[i];
			b[i]--;
			pb[b[i]]=i;
		}
		for(i=0;i<n;i++)tvis[i]=0;
		for(i=n-1;i>-1;i--)
		{
			t=pb[a[i]];
			cntsg[i]=0;
			wp[i]=-1;
			for(j=0;j<n;j++)
			{
				cvis[j]=0;
				zvis[j]=0;
			}
			ccnt=0;
			r=-1;
			for(j=0;i+j<n&&t+j<n;j++)
			{
				if(cvis[a[i+j]]==0)ccnt++;
				cvis[a[i+j]]++;
				if(cvis[a[i+j]]==0)ccnt--;
				if(cvis[b[t+j]]==0)ccnt++;
				cvis[b[t+j]]--;
				if(cvis[b[t+j]]==0)ccnt--;
				if(ccnt==0)
				{
					zvis[i+j]=1;
					r=i+j;
