					}
					else wp[i]=-1;
				}
			}
			if(wp[i]!=-1)cntsg[i]--;
			tvis[i]=1;
		}
		cntsg[n]=0;
		wp[n]=-1;
		for(i=0;i<n;i++)
		{
			cvis[i]=0;
			zvis[i]=0;
		}
		ccnt=0;
		r=-1;
		for(i=0;i<n;i++)
		{
			if(cvis[a[i]]==0)ccnt++;
			cvis[a[i]]++;
			if(cvis[a[i]]==0)ccnt--;
			if(cvis[b[i]]==0)ccnt++;
			cvis[b[i]]--;
