vector<int> g[maxn], e[maxn], g2[maxn];
int n, m;

void dfs(int v, int p) {
    sz[v] = 1;
    used[v] = true;
    for(int to : g[v]) {
        if(to == p) {
            continue;
        }

        dfs(to, v);

        if(sz[to] % 2 == 0) {
            e[to].push_back(v);
            bad[v]++;
        }
        else {
            e[v].push_back(to);
            bad[to]++;
        }

        sz[v] += sz[to];
    }
}

void solve {
    cin >> n;
    for(int i = 1; i <= n; i++) {
        cin >> a[i];
        a[i] %= 2;
        del[i] = cnt[i] = sz[i] = 0;
        bad[i] = used[i] = 0;
