		    			putchar('B'),putchar('R'),rb --;
		    	}
		    	else{
		    		while(rb > 0)
	    				putchar('R'),putchar('B'),rb --;
		    	}
		}
		else if(r > 0){
			putchar('R');
			while(rg > 0)
				putchar('G'),putchar('R'),rg --;
