 if (mem.count(p))
 return mem[p];
 int mid = 3 - from - to;
 if (n == 1) {
 return mem[p] = min(t[from][mid] + t[mid][to], t[from][to]);
 }
 return mem[p] = min(calc(from, mid, n - 1) + t[from][to] + calc(mid, to, n - 1),
