int t[N];
vector ys;

inline void inc(int i, int val) {
 for ( ; i < sz(ys); i |= i + 1)
 t[i] += val;
}

inline int sum(int i) {
 int ans = 0;
 for ( ; i >= 0; i = (i & (i + 1)) - 1)
 ans += t[i];
 return ans;
}

int ans[N];

void solve {
