int n;
ld p[N][N];

bool read {
 if (!(cin >> n)) return false;
 forn(i, n) forn(j, n) assert(cin >> p[i][j]);
 return true;
}

ld z[EXPN][N];

ld solve(int mask, int i) {
 ld& ans = z[mask][i];
 if (ans > -0.5) return ans;
 if (mask == (1 << n) - 1) return ans = !i;
 ans = 0;
 forn(j, n)
 if (!(mask & (1 << j))) {
 ld cur = 0;
 cur += solve(mask | (1 << j), i) * p[i][j];
 cur += solve(mask | (1 << j), j) * p[j][i];
 ans = max(ans, cur);
 }
 return ans;
}

void solve {
 if (n == 1) {
 puts("1");
 return;
 }

