 forn(i, n)
 forn(j, i) {
 int mask = (1 << i) | (1 << j);
 ld cur = 0;
 cur += solve(mask, i) * p[i][j];
 cur += solve(mask, j) * p[j][i];
 ans = max(ans, cur);
