Let's interpret the problem geometrically: the pairs from the set are the lines and the problem to find to topmost intersection of the vertical line with the lines from the set.

Let's split the queries to $[formula]$ blocks. Consider the lines added before the current block and that will not deleted in the current block. Let's build the lower envelope by that lines. Now to calculate the answer to the query we should get maximum over the lines from the envelope and the lines from the block before the current query that is not deleted yet. There are no more than $[formula]$ lines from the block, so we can iterate over them. Let's find the answers from the envelope for all queries of the third type from the block at once: we should sort them and iterate over envelope using two pointers technique.

C++ solution

```
const int N = 300300;

int n;
int t[N], a[N], b[N], id[N], q[N];

bool read {
 if (!(cin >> n)) return false;
 forn(i, n) {
 assert(scanf("%d", &t[i]) == 1);
 if (t[i] == 1) {
 assert(scanf("%d%d", &a[i], &b[i]) == 2);
 } else if (t[i] == 2) {
 assert(scanf("%d", &id[i]) == 1);
 id[i]--;
 } else if (t[i] == 3) {
 assert(scanf("%d", &q[i]) == 1);
 } else throw;
 }
 return true;
}

bool in_set[N], deleted[N];
vector> lines;
vector envelope;

void build_envelope {
 envelope.clear;
 envelope.reserve(n);

 forn(ii, sz(lines)) {
 int i = lines[ii].y;
 if (in_set[i] && !deleted[i]) {
 assert(t[i] == 1);
 pti c(a[i], b[i]);
 while (!envelope.empty) {
 pti b = envelope.back;
 if (b.x == c.x) {
 envelope.pop_back;
 continue;
 } else if (sz(envelope) > 1) {
 pti a = envelope[sz(envelope) - 2];

 ld xc = ld(c.y - a.y) / (a.x - c.x);
 ld xb = ld(b.y - a.y) / (a.x - b.x);

 if (xc < xb) {
 envelope.pop_back;
 continue;
 }
 }
 break;
 }
 envelope.pb(c);
 }
 }
}

li ans[N];
vector qs;

void process_qs {
 sort(all(qs));

 int p = 0;
 forn(i, sz(qs)) {
 li q = qs[i].x;
 int id = qs[i].y;

 while (p + 1 < sz(envelope)) {
 li cval = envelope[p].x * q + envelope[p].y;
 li nval = envelope[p + 1].x * q + envelope[p + 1].y;
 if (cval > nval) break;
 p++;
 }

 if (p < sz(envelope)) {
 ans[id] = envelope[p].x * q + envelope[p].y;
 }
 }
}

void solve {
 lines.clear;
 lines.reserve(n);
 forn(i, n) if (t[i] == 1) lines.pb(mp(mp(a[i], b[i]), i));
 sort(all(lines));

 memset(in_set, false, sizeof(in_set));
 memset(deleted, false, sizeof(deleted));
 forn(i, n) ans[i] = LLONG_MIN;

 int blen = int(sqrtl(n));
 blen = 2500;
 for (int l = 0; l < n; l += blen) {
 int r = min(n, l + blen);

 memset(deleted, false, sizeof(deleted));
 fore(i, l, r) if (t[i] == 2) deleted[id[i]] = true;
 build_envelope;

 qs.clear;
 qs.reserve(r - l);
 fore(i, l, r) if (t[i] == 3) qs.pb(mp(q[i], i));
 process_qs;

 fore(i, l, r) {
 if (t[i] == 1) in_set[i] = true;
 else if (t[i] == 2) in_set[id[i]] = false;
 else {
 fore(j, l, r) {
 if (t[j] == 1 && in_set[j])
 ans[i] = max(ans[i], li(a[j]) * q[i] + b[j]);
 else if (t[j] == 2 && in_set[id[j]])
 ans[i] = max(ans[i], li(a[id[j]]) * q[i] + b[id[j]]);
 }
 if (ans[i] != LLONG_MIN) printf("%lldn", ans[i]);
 else puts("EMPTY SET");
 }
 }
 }
}
```

