 public static int zz(char let) {
 int N = let.length;
 int z = new int[N];
 int L = 0, R = 0;
 for (int i = 1; i < N; i++) {
 if (i > R) {
 L = R = i;
 while (R < N && let[R - L] == let[R])
 R++;
 z[i] = R - L;
 R--;
 } else {
 int k = i - L;
 if (z[k] < R - i + 1)
 z[i] = z[k];
 else {
 L = i;
 while (R < N && let[R - L] == let[R])
 R++;
 z[i] = R - L;
 R--;
 }
 }
 }
 z[0] = N;
 return z;
 }

 private static boolean isDAG(ArrayList graph) {
 int n = graph.length;
 int indeg = new int[n];
 for (int i = 0; i < n; i++) for (int x : graph[i]) indeg[x]++;
 int queue = new int[n];
 int front = 0, back = 0, idx = 0;

 for (int i = 0; i < indeg.length; i++)
 if (indeg[i] == 0)
 queue[back++] = i;

 while (front != back) {
 int node = queue[front++];
 for (int next : graph[node]) {
 if (--indeg[next] == 0) {
 queue[back++] = next;
 }
 }
 }

 return front == n;
 }

