vector < pair < int, int > > edge[maxn];
int used[maxn];
int from[maxn];
int where[maxn];
ld dist[maxn];

void dfs( int v, ld prevTime ) {
 used[v] = true;
 int sz = edge[v].size();
 ld bestTime = 2.0L / sz;
 ld nextTime = prevTime + bestTime;
 if ( nextTime >= 2.0L )
 nextTime -= 2.0L;
 for ( int j = 0; j < sz; j++ ) {
 int id = edge[v][j].f;
 int to = edge[v][j].s;
 if ( used[to] )
 continue;

 ld toTime;
 if ( nextTime <= 1.0L ) {
 from[id] = to;
 where[id] = v;
 dist[id] = 1.0L - nextTime;
 toTime = nextTime + 1.0L;
 } else {
 from[id] = v;
 where[id] = to;
 dist[id] = 2.0L - nextTime;
 toTime = nextTime - 1.0L;
 }

 dfs( to, toTime );

 nextTime = nextTime + bestTime;
 if ( nextTime >= 2.0L )
 nextTime -= 2.0L;
 }
